/* ===================== 1. 經貿資訊 ===================== */
BANK.modules.push({
id:'m1', name:'經貿資訊', icon:'🌏', short:'台灣貿易環境、主管機關、國際組織',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>把「做國貿」想成參加一場國際球賽:你得知道<b>裁判是誰</b>(主管機關)、<b>聯盟規則</b>(WTO 等國際組織)、以及<b>球隊的主要對手和隊友</b>(主要貿易夥伴)。這章就是賽前的「賽況簡報」。</p></div>
<h4>台灣的貿易主管機關</h4>
<table><tr><th>機關</th><th>管什麼</th><th>記憶點</th></tr>
<tr><td>經濟部國際貿易署</td><td>貿易政策、進出口管理、出進口廠商登記</td><td>2023 年由「國際貿易局」改制升格</td></tr>
<tr><td>財政部關務署</td><td>海關:通關、關稅、查緝</td><td>「關」= 關稅、報關</td></tr>
<tr><td>外貿協會(TAITRA)</td><td>拓銷推廣、展覽(如台北國際電腦展)</td><td>幫廠商「賣出去」的推手</td></tr>
<tr><td>中華民國輸出入銀行</td><td>輸出保險、出口融資</td><td>政府的「出口保險公司」</td></tr>
<tr><td>台北市進出口商業同業公會(IEAT)</td><td>產業公會;主辦國際貿易大會考</td><td>就是這個考試的主辦單位</td></tr>
<tr><td>中央銀行</td><td>匯率、外匯管理</td><td>新台幣的守門員</td></tr></table>
<h4>重要國際組織與協定</h4>
<ul><li><b>WTO(世界貿易組織)</b>:1995 年成立,前身 GATT。台灣 2002 年以「台澎金馬個別關稅領域」名義加入。核心原則:<b>最惠國待遇</b>(給一國的優惠要給所有會員)、<b>國民待遇</b>(進口品在國內不能被歧視)。</li>
<li><b>ICC(國際商會)</b>:制定 <b>Incoterms(國貿條規)</b>、<b>UCP600(信用狀統一慣例)</b>、<b>URC522(託收統一規則)</b>——考試最常考的三套「遊戲規則」都出自 ICC。</li>
<li><b>RCEP、CPTPP</b>:亞太區域的自由貿易協定;台灣已申請加入 CPTPP。</li>
<li><b>ECFA</b>:兩岸經濟合作架構協議(2010)。</li>
<li><b>HS Code(國際商品統一分類制度)</b>:全球通用的商品「身分證號碼」,前 6 碼國際通用,台灣稅則用到 11 碼(CCC Code)。</li></ul>
<div class="card advanced"><span class="deftag">進階補充</span><p>台灣出口最大宗是電子零組件與資通訊產品,主要出口市場為中國大陸(含香港)、美國、東協;近年對美國出口比重明顯上升。經貿時事每年會變,考前一週看一下國際貿易署與財政部的最新新聞稿最保險。</p></div>`,
questions:[
{q:'目前我國負責貿易政策、進出口管理與出進口廠商登記的主管機關是?',o:['財政部關務署','經濟部國際貿易署','外貿協會','中央銀行'],a:1,e:'國際貿易署(2023 年由國際貿易局改制)負責貿易政策與進出口管理;關務署管海關通關與關稅;外貿協會做拓銷推廣;央行管匯率外匯。'},
{q:'制定 Incoterms(國貿條規)與 UCP600(信用狀統一慣例)的國際組織是?',o:['WTO','ICC 國際商會','IMF','世界銀行'],a:1,e:'國際商會(International Chamber of Commerce, ICC)制定 Incoterms、UCP600、URC522 等貿易慣例。WTO 是政府間的貿易談判組織,不制定這類民間慣例。'},
{q:'WTO 的「最惠國待遇」原則是指?',o:['會員給予某一會員的貿易優惠,必須同樣給予所有會員','進口品在國內市場不得受到比國產品差的待遇','開發中國家可享免關稅','會員間不得使用反傾銷稅'],a:0,e:'最惠國待遇(MFN)= 對一國的優惠要「一視同仁」給所有會員;「進口品不得比國產品差」是國民待遇原則,兩者是 WTO 兩大不歧視原則。'},
{q:'台灣加入 WTO 時所使用的名稱是?',o:['中華民國','台灣共和國','台澎金馬個別關稅領域','中華台北'],a:2,e:'台灣於 2002 年以「台灣、澎湖、金門及馬祖個別關稅領域」(簡稱台澎金馬個別關稅領域)名義加入 WTO;「中華台北」是奧運等場合的名稱。'},
{q:'HS Code(國際商品統一分類制度)的前幾碼為國際通用?',o:['4 碼','6 碼','8 碼','11 碼'],a:1,e:'HS 前 6 碼全球一致,各國再自行往下細分;台灣的 CCC Code 為 11 碼(10 碼稅則 + 1 碼檢查號)。'},
{q:'負責承保「輸出保險」、協助廠商規避國外買主信用風險的政府機構是?',o:['中央銀行','中華民國輸出入銀行','財政部關務署','外貿協會'],a:1,e:'輸出入銀行是政府政策性銀行,提供輸出保險與出口融資;一般產物保險公司承保的是貨物運輸險,兩者不同。'},
{q:'主辦「國際貿易大會考」的單位是?',o:['經濟部國際貿易署','台北市進出口商業同業公會','外貿協會','教育部'],a:1,e:'國貿大會考由台北市進出口商業同業公會(IEAT)主辦,是產業界認可的國貿專業證照。'},
{q:'兩岸於 2010 年簽署的經濟合作協議是?',o:['RCEP','CPTPP','ECFA','FTA'],a:2,e:'ECFA = 兩岸經濟合作架構協議(Economic Cooperation Framework Agreement)。RCEP、CPTPP 是亞太多邊自由貿易協定;FTA 是自由貿易協定的通稱。'},
{q:'關於外貿協會(TAITRA)的主要功能,下列何者正確?',o:['核發輸出許可證','辦理出口報關','推動貿易拓銷、舉辦國際展覽','管理外匯與匯率'],a:2,e:'外貿協會是半官方推廣機構,主要做市場拓銷、展覽(如台北國際電腦展、台北國際食品展)與市場資訊。許可證是國際貿易署、報關是海關、匯率是央行。'},
{q:'WTO 的前身是?',o:['GATT 關稅暨貿易總協定','IMF 國際貨幣基金','OECD 經濟合作暨發展組織','APEC 亞太經合會'],a:0,e:'GATT(1947)是多邊關稅協定,1995 年烏拉圭回合後由 WTO 取代並擴大涵蓋服務貿易與智慧財產權。'},
{q:'下列何者是台灣近年出口金額最大的產品類別?',o:['農產品','紡織品','電子零組件與資通訊產品','汽車'],a:2,e:'台灣是半導體與資通訊產品的重要生產基地,電子零組件(晶片)與資通訊產品長期是出口最大宗。'},
{q:'我國廠商辦理進出口業務前,依規定應先向何機關辦理「出進口廠商登記」?',o:['財政部','經濟部國際貿易署','當地縣市政府','外貿協會'],a:1,e:'出進口廠商登記由國際貿易署受理(線上申辦),完成登記才能以廠商名義報關進出口。'}
]});

/* ===================== 2. 基本概念及流程 ===================== */
BANK.modules.push({
id:'m2', name:'國際貿易基本概念及流程', icon:'🔁', short:'進出口流程、貿易型態、當事人',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>國際貿易就像「跨國網購」的放大版:買家找賣家、談價格、下單、付錢、賣家出貨、物流送到、買家收貨——只是每一步都多了「海關」「銀行」「船公司」「保險公司」這些中間角色,而且金額大到不能靠信任,必須靠<b>單據</b>來說話。</p></div>
<h4>出口流程(記順序!)</h4>
<ol><li><b>市場調查與尋找買主</b>(展覽、B2B 平台)</li><li><b>詢價 → 報價 → 還價 → 接受</b>(契約成立)</li><li><b>簽訂契約</b>(Sales Confirmation / Purchase Order / Proforma Invoice)</li><li><b>買方開信用狀</b>(若採 L/C)→ 賣方收到 L/C 後審查</li><li><b>備貨、報驗</b>(如需檢驗)</li><li><b>洽訂艙位(Booking)、投保</b>(CIF/CIP 由賣方保)</li><li><b>出口報關、裝船</b> → 取得提單 B/L</li><li><b>裝船通知(Shipping Advice)</b>給買方</li><li><b>製作單據、押匯(Negotiation)</b>:向銀行提示單據取得貨款</li><li><b>售後服務、索賠處理</b></li></ol>
<h4>進口流程</h4>
<ol><li>詢價、訂約</li><li>申請開狀(向銀行申請 L/C)</li><li>買保險(FOB/CFR 由買方保)</li><li>接到裝船通知 → 準備贖單</li><li>付款贖單(向銀行付款取得提單等單據)</li><li>進口報關、繳稅、提貨</li><li>驗貨、若有問題提出索賠</li></ol>
<h4>常見貿易型態</h4>
<table><tr><th>型態</th><th>意思</th><th>一句話</th></tr>
<tr><td>直接貿易 / 間接貿易</td><td>買賣雙方直接成交 / 透過第三國中間商</td><td>有沒有「中間人」</td></tr>
<tr><td>三角貿易(Triangular Trade)</td><td>台灣接單、第三地出貨、貨不經過台灣</td><td>台灣接單、海外出貨</td></tr>
<tr><td>轉口貿易(Entrepot)</td><td>貨物先進到中繼地再出口</td><td>貨「路過」中繼港</td></tr>
<tr><td>OEM / ODM / OBM</td><td>代工製造 / 設計+製造 / 自有品牌</td><td>O = original;E 製造、D 設計、B 品牌</td></tr>
<tr><td>相對貿易(Counter Trade)</td><td>以貨易貨、補償貿易</td><td>不完全用錢交易</td></tr>
<tr><td>加工貿易</td><td>進口原料加工後再出口</td><td>保稅區常見</td></tr></table>
<h4>當事人英文(考英文也會用到)</h4>
<p>出口商 Exporter / 賣方 Seller;進口商 Importer / 買方 Buyer;託運人 Shipper;受貨人 Consignee;運送人 Carrier;報關行 Customs Broker;貨運承攬業 Freight Forwarder(幫你安排運輸的「旅行社」)。</p>`,
questions:[
{q:'在信用狀付款的出口流程中,下列步驟的正確順序是?①押匯 ②接到信用狀 ③裝船 ④報價成交',o:['④②③①','②④③①','④③②①','②③④①'],a:0,e:'先成交(④)、買方才會開狀、賣方接到 L/C(②)、然後備貨裝船(③)、最後拿單據去銀行押匯(①)。記住:沒有契約不會有信用狀,沒有裝船不會有提單,沒有提單不能押匯。'},
{q:'台灣公司接到美國客戶訂單後,直接由越南工廠出貨給美國,貨物不經過台灣,這種貿易型態稱為?',o:['轉口貿易','三角貿易','加工貿易','相對貿易'],a:1,e:'三角貿易:接單地、出貨地、收貨地是三個不同國家,貨物直接從生產地運到買方。轉口貿易的貨物會「經過」中繼地。'},
{q:'OEM 是指?',o:['自有品牌生產','原廠委託代工製造','原廠委託設計並製造','相對貿易'],a:1,e:'OEM = Original Equipment Manufacturing(代工製造,設計由客戶提供);ODM 多了「設計」(Design);OBM 是自有品牌(Brand)。'},
{q:'買賣雙方不透過第三國中間商而直接成交,稱為?',o:['間接貿易','直接貿易','過境貿易','轉口貿易'],a:1,e:'直接貿易就是「沒有中間人」;透過第三國中間商就是間接貿易。'},
{q:'出口商將貨物裝船後,通知進口商船名、開航日、貨物明細等,這份通知稱為?',o:['Shipping Advice 裝船通知','Shipping Order 裝貨單','Booking Note 訂艙單','Delivery Order 提貨單'],a:0,e:'裝船通知(Shipping Advice)是賣方在裝船後給買方的通知,讓買方能準備投保(FOB/CFR)與提貨。S/O 是船公司給託運人的裝貨指示,D/O 是提貨用。'},
{q:'替進出口商安排運輸、併櫃、代辦文件的業者稱為?',o:['Customs Broker','Freight Forwarder','Carrier','Consignee'],a:1,e:'Freight Forwarder(貨運承攬業)像「貨物的旅行社」;Customs Broker 是報關行;Carrier 是實際的運送人(船公司、航空公司);Consignee 是受貨人。'},
{q:'進口商向銀行付款取回提單等單據的動作稱為?',o:['押匯','贖單','託收','背書'],a:1,e:'贖單 = 進口商付錢「贖回」單據;押匯是出口商拿單據向銀行「先拿錢」;託收是透過銀行代收貨款。'},
{q:'下列何者不是國際貿易與國內貿易的主要差異?',o:['幣別不同','語言與法律制度不同','運輸距離長、風險高','都必須簽訂書面契約'],a:3,e:'國內外交易都可以口頭成立契約,並非國際貿易獨有的差異;真正的差異在幣別、法律、語言、距離與風險。'},
{q:'進口原料在保稅區加工後再出口,這種型態屬於?',o:['加工貿易','三角貿易','相對貿易','平行輸入'],a:0,e:'加工貿易:原料進來加工後再出去,常在保稅區(免稅進口、加工後出口)進行。'},
{q:'ODM 與 OEM 的主要差別在於?',o:['是否使用自有品牌','製造商是否負責產品設計','是否經由代理商銷售','出口數量的多寡'],a:1,e:'ODM 多了 Design——製造商自己設計產品再給客戶掛牌;OEM 只按客戶設計代工。有自己品牌才是 OBM。'},
{q:'在 L/C 交易中,出口商裝船後取得的最重要單據是?',o:['保險單','提單(B/L)','商業發票','產地證明書'],a:1,e:'提單是運送人簽發的「貨物收據 + 運送契約 + 物權憑證」,沒有提單就無法押匯也無法提貨。'},
{q:'Consignee 在提單上指的是?',o:['託運人','受貨人','運送人','通知人'],a:1,e:'Consignee = 受貨人(收貨的人);Shipper = 託運人;Carrier = 運送人;Notify Party = 到貨通知人。'},
{q:'從國外進口原廠商品,但並非透過原廠授權的代理商,這種進口稱為?',o:['三角貿易','平行輸入(水貨)','轉口貿易','相對貿易'],a:1,e:'平行輸入俗稱「水貨」:商品是真品,只是不走原廠授權的代理通路。'},
{q:'買方在詢價之後,賣方針對其需求提出價格與條件,稱為?',o:['Inquiry','Offer','Acceptance','Order'],a:1,e:'流程是 Inquiry(詢價)→ Offer(報價)→ Counter-offer(還價)→ Acceptance(接受)。賣方提出價格條件就是 Offer。'}
]});

/* ===================== 3. 契約條件 ===================== */
BANK.modules.push({
id:'m3', name:'國際貿易契約條件', icon:'📜', short:'品質、數量、包裝、價格(Incoterms 2020)、交貨、付款、保險',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>買賣契約像「訂做蛋糕的訂單」:要說清楚<b>什麼口味</b>(品質)、<b>幾吋幾個</b>(數量)、<b>怎麼裝盒</b>(包裝)、<b>多少錢、含不含外送</b>(價格條件)、<b>什麼時候送到哪</b>(交貨)、<b>怎麼付款</b>(付款)、<b>摔壞了誰賠</b>(保險)。每一項都是考題來源。</p></div>
<h4>品質條件(怎麼說「要什麼樣的貨」)</h4>
<table><tr><th>方式</th><th>用法</th></tr>
<tr><td>樣品(Sample)</td><td>憑樣交易;賣方樣品 seller's sample、買方樣品 buyer's sample、對等樣品 counter sample(賣方照買方樣品做出來再確認)</td></tr>
<tr><td>規格 / 等級 / 標準</td><td>工業品用規格書、農產品用等級</td></tr>
<tr><td>FAQ(Fair Average Quality)</td><td>「平均中等品質」,農產品常用</td></tr>
<tr><td>GMQ(Good Merchantable Quality)</td><td>「上好可銷品質」,木材、冷凍魚常用</td></tr>
<tr><td>品牌 / 商標、目錄說明書</td><td>名牌貨、機械設備</td></tr></table>
<h4>數量條件</h4>
<ul><li><b>重量</b>:毛重 Gross Weight(含包裝)、淨重 Net Weight(不含包裝)、公噸 M/T = 1,000 kg、長噸 L/T ≈ 1,016 kg、短噸 S/T ≈ 907 kg。</li>
<li><b>寬容條款(More or Less Clause)</b>:「數量可增減 5%」,散裝貨常用。</li>
<li><b>UCP600 規定</b>:信用狀若未禁止,數量可有 <b>±5%</b> 的寬容(但以「件數」計的貨物除外,且總金額不得超過 L/C 金額);金額或數量前有 "about / approximately" 則 <b>±10%</b>。</li></ul>
<h4>包裝條件與嘜頭</h4>
<p>嘜頭(Shipping Marks)是外箱上的標記,包含:<b>主嘜</b>(買方名稱縮寫、目的港、箱號)、<b>副嘜</b>、<b>注意標誌</b>(如 THIS SIDE UP、FRAGILE)。中性包裝(Neutral Packing)= 不標示生產國與廠商,OEM 常用。</p>
<h4>價格條件:Incoterms 2020(必考中的必考)</h4>
<p>Incoterms 只規定<b>「風險在哪轉移、費用誰付、誰辦通關」</b>,<b>不規定</b>所有權移轉、付款方式、違約處理。2020 版共 11 種,分兩大類:</p>
<table><tr><th>條件</th><th>中文</th><th>賣方責任到哪</th><th>運費</th><th>保險</th><th>進口通關</th></tr>
<tr><td colspan="6"><b>任何運輸方式(7 種)</b></td></tr>
<tr><td>EXW</td><td>工廠交貨</td><td>賣方工廠內備妥貨物(不裝車)</td><td>買</td><td>買</td><td>買(出口通關也是買方)</td></tr>
<tr><td>FCA</td><td>貨交運送人</td><td>指定地點交給買方指定的運送人(在賣方處所需裝車)</td><td>買</td><td>買</td><td>買</td></tr>
<tr><td>CPT</td><td>運費付訖</td><td>交給運送人即風險轉移,但運費賣方付到目的地</td><td>賣</td><td>買</td><td>買</td></tr>
<tr><td>CIP</td><td>運保費付訖</td><td>同 CPT,但賣方另投保(2020 起最低 ICC(A))</td><td>賣</td><td>賣</td><td>買</td></tr>
<tr><td>DAP</td><td>目的地交貨</td><td>貨到目的地、運輸工具上「未卸貨」</td><td>賣</td><td>—</td><td>買</td></tr>
<tr><td>DPU</td><td>目的地卸貨後交貨</td><td>貨到目的地並「卸貨完成」(唯一要求賣方卸貨)</td><td>賣</td><td>—</td><td>買</td></tr>
<tr><td>DDP</td><td>稅訖交貨</td><td>賣方連進口關稅都付,責任最重</td><td>賣</td><td>—</td><td>賣</td></tr>
<tr><td colspan="6"><b>僅限海運、內河運輸(4 種)</b></td></tr>
<tr><td>FAS</td><td>船邊交貨</td><td>貨放到指定裝運港的船邊(碼頭或駁船)</td><td>買</td><td>買</td><td>買</td></tr>
<tr><td>FOB</td><td>船上交貨</td><td>貨「裝上船」風險轉移</td><td>買</td><td>買</td><td>買</td></tr>
<tr><td>CFR</td><td>運費在內</td><td>風險同 FOB(裝上船),但賣方付到目的港的運費</td><td>賣</td><td>買</td><td>買</td></tr>
<tr><td>CIF</td><td>運保費在內</td><td>風險同 FOB,賣方付運費+保險(最低 ICC(C)、110%)</td><td>賣</td><td>賣</td><td>買</td></tr></table>
<div class="card def"><span class="deftag">秒殺記憶法</span><p><b>E → F → C → D</b> 賣方責任由輕到重。<b>F 組</b>:主運費買方付;<b>C 組</b>:主運費賣方付「但風險在出口地就轉移」(這是最愛考的陷阱:CFR/CIF 的風險在裝船港轉移,不是在目的港!);<b>D 組</b>:賣方送到目的地。<b>只有 FAS/FOB/CFR/CIF 限海運</b>,裝貨櫃走複合運輸應該用 FCA/CPT/CIP。</p></div>
<h4>交貨、付款、保險條件</h4>
<ul><li>交貨期常用「裝船日」認定;L/C 上的 Latest Date of Shipment 是最後裝船日。</li><li>付款條件詳見第 5 章(L/C、D/P、D/A、T/T、O/A)。</li><li>保險條件:CIF/CIP 由賣方投保,保額慣例為<b>發票金額的 110%</b>(多的 10% 是預期利潤)。</li></ul>`,
questions:[
{q:'依 Incoterms 2020,下列哪一組貿易條件「只適用於海運及內河運輸」?',o:['EXW、FCA、CPT、CIP','FAS、FOB、CFR、CIF','DAP、DPU、DDP','FCA、FOB、CPT、CIF'],a:1,e:'F-A-S、F-O-B、C-F-R、C-I-F 四種以「船」為交貨點,只能用在海運/內河;其餘 7 種適用任何運輸方式(含貨櫃複合運輸)。'},
{q:'CIF 條件下,貨物的風險於何時由賣方移轉給買方?',o:['貨物抵達目的港時','貨物在裝運港裝上船時','買方付清貨款時','貨物交給買方倉庫時'],a:1,e:'C 組(CFR、CIF、CPT、CIP)的關鍵陷阱:賣方付運費到目的地,但「風險」在出口地就轉移——CIF 是貨物在裝運港裝上船時。'},
{q:'Incoterms 2020 中,唯一要求賣方在目的地「卸貨」後才算交貨的條件是?',o:['DAP','DPU','DDP','CIP'],a:1,e:'DPU(Delivered at Place Unloaded)是 2020 年新名稱(取代 2010 的 DAT),賣方須卸貨;DAP 是在運輸工具上未卸貨;DDP 賣方要付進口稅但不必卸貨。'},
{q:'在 DDP 條件下,進口國的關稅由誰負擔?',o:['買方','賣方','運送人','雙方平均'],a:1,e:'DDP = Delivered Duty Paid「稅訖交貨」,賣方責任最重,連進口通關與關稅都要負責。這是 11 種條件中唯一由賣方辦進口通關的。'},
{q:'EXW 條件下,出口通關手續由誰辦理?',o:['賣方','買方','運送人','報關行自行決定'],a:1,e:'EXW 賣方責任最輕,只要在自己工廠把貨備好;連出口通關和裝車都是買方的事。實務上外國買方難以辦出口報關,所以常建議改用 FCA。'},
{q:'關於 CIP 與 CIF 的保險規定,依 Incoterms 2020 下列何者正確?',o:['兩者皆最低投保 ICC(C)','CIF 最低 ICC(A),CIP 最低 ICC(C)','CIP 最低 ICC(A),CIF 最低 ICC(C)','兩者皆最低投保 ICC(A)'],a:2,e:'2020 版把 CIP 的最低保險提高到 ICC(A)(全險),CIF 維持 ICC(C)(基本險)。記法:CIP 常用於高價貨櫃貨物,所以保得多。'},
{q:'FOB 條件下,海上運費由誰支付?',o:['賣方','買方','船公司','由信用狀決定'],a:1,e:'F 組(FCA、FAS、FOB)的共同點:主運費由買方支付。FOB 賣方只負責把貨裝上買方指定的船。'},
{q:'Incoterms 規範的內容「不包括」下列何者?',o:['風險移轉時點','費用負擔的劃分','貨物所有權的移轉','進出口通關由誰辦理'],a:2,e:'Incoterms 只講風險、費用、通關與交貨義務,不涉及所有權移轉、付款方式、違約救濟——這些要在契約另外約定。'},
{q:'信用狀未禁止的情況下,依 UCP600 貨物數量的寬容範圍為?',o:['±3%','±5%(但以件數計者除外)','±10%','不允許任何增減'],a:1,e:'UCP600 第 30 條:數量可 ±5%,前提是 L/C 沒禁止、貨物不是以包裝單位或件數計、且動支總額不超過 L/C 金額。若有 about/approximately 則 ±10%。'},
{q:'買賣契約中「FAQ」品質條件是指?',o:['常見問答','平均中等品質','上好可銷品質','工廠檢驗合格'],a:1,e:'FAQ = Fair Average Quality,農產品交易常用「當季平均中等品質」;GMQ = Good Merchantable Quality 上好可銷品質。'},
{q:'買方提供樣品,賣方依樣仿製後再寄回請買方確認的樣品稱為?',o:["Seller's sample",'Counter sample 對等樣品','Shipping sample','Reference sample'],a:1,e:'對等樣品(Counter Sample)= 賣方照買方樣品做出來的「回樣」,經買方確認後作為交貨品質標準。'},
{q:'包裝上不標示生產國別與製造商名稱的包裝方式稱為?',o:['中性包裝','出口包裝','保護包裝','綠色包裝'],a:0,e:'中性包裝(Neutral Packing)常用於 OEM 或轉口貿易,方便買方貼自己的品牌。'},
{q:'1 公噸(Metric Ton)等於幾公斤?',o:['907','1,000','1,016','2,000'],a:1,e:'M/T = 1,000 kg;長噸 L/T(英制)約 1,016 kg;短噸 S/T(美制)約 907 kg。'},
{q:'FCA 條件下,若交貨地點在賣方營業處所,貨物裝上買方派來的卡車的「裝車」責任屬於?',o:['買方','賣方','運送人','雙方協商'],a:1,e:'FCA 的規定:在賣方處所交貨,賣方要負責裝上買方的運輸工具;若在其他地點交貨,則賣方不必卸貨。這是 FCA 與 EXW 的重要差別。'},
{q:'契約中訂明「Shipment during May」,買方希望知道確切裝船日期,最適合的做法是?',o:['要求賣方於裝船後發出裝船通知','要求賣方改採 EXW','要求賣方改採 D/A 付款','要求船公司直接通知'],a:0,e:'裝船通知(Shipping Advice)就是讓買方掌握船名、裝船日與貨物明細的文件,方便買方投保與安排提貨。'},
{q:'關於 CFR 與 CIF 的差別,下列何者正確?',o:['CFR 賣方需投保,CIF 不需','CIF 比 CFR 多了賣方投保的義務','CFR 風險在目的港轉移','CIF 只適用空運'],a:1,e:'CIF = CFR + Insurance:多了賣方投保(最低 ICC(C)、110%)。兩者風險都在裝船港裝上船時轉移,都只限海運。'},
{q:'嘜頭(Shipping Mark)的主要功能是?',o:['證明貨物產地','便於辨識、搬運與核對貨物','決定貨物關稅','代替提單'],a:1,e:'嘜頭是外箱上的標記(買方代號、目的港、箱號、注意標誌),幫助裝卸與海關核對,和產地證明或關稅無關。'}
]});

/* ===================== 4. 報價、接受與契約訂定 ===================== */
BANK.modules.push({
id:'m4', name:'報價、接受與契約訂定', icon:'🤝', short:'詢價、報價種類、還價、接受、契約文件',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>買賣成立像打乒乓球:買方發球(詢價)、賣方回球(報價)、買方殺球(還價)、有一方接住球不再回擊(接受)→ 這一分才算數(契約成立)。<b>還價 = 拒絕原報價 + 提出新報價</b>,所以一旦還價,原報價就失效了。</p></div>
<h4>報價的種類</h4>
<table><tr><th>種類</th><th>意思</th><th>關鍵</th></tr>
<tr><td>穩固報價(Firm Offer)</td><td>有效期內賣方不得撤回,買方一接受契約即成立</td><td>Firm = 有效期內「說話算話」</td></tr>
<tr><td>自由報價 / 條件報價(Free / Conditional Offer)</td><td>不受拘束,例如 "subject to our final confirmation"(以我方最後確認為準)、"subject to prior sale"(先售為主)</td><td>買方接受後仍要賣方確認才成立</td></tr>
<tr><td>還價(Counter Offer)</td><td>對報價內容作變更後回覆</td><td>等於拒絕原報價,原報價失效</td></tr>
<tr><td>聯合報價(Combined Offer)</td><td>多項商品綁在一起報價,必須整批接受</td><td>不能只挑其中一項</td></tr></table>
<h4>接受(Acceptance)的要件</h4>
<ul><li>必須在<b>有效期限內</b>;逾期接受(Late Acceptance)無效,除非賣方同意。</li><li>必須<b>無條件、完全一致</b>(鏡像原則);附加條件就是還價。</li><li>沉默不是接受。</li><li>報價可以在對方接受前<b>撤回</b>(Withdrawal / Revocation),但穩固報價在有效期內原則上不可撤回。</li></ul>
<h4>契約文件</h4>
<table><tr><th>文件</th><th>誰出</th><th>用途</th></tr>
<tr><td>Proforma Invoice(P/I,預期發票 / 形式發票)</td><td>賣方</td><td>報價單的正式版,買方常拿去申請開狀或進口許可</td></tr>
<tr><td>Sales Confirmation(S/C,售貨確認書)</td><td>賣方</td><td>賣方版的契約</td></tr>
<tr><td>Purchase Order(P/O,訂購單)</td><td>買方</td><td>買方版的契約</td></tr>
<tr><td>Purchase Confirmation(購貨確認書)</td><td>買方</td><td>買方確認成交條件</td></tr></table>
<div class="card advanced"><span class="deftag">進階補充</span><p>報價單上常見有效期寫法:"This offer is valid until June 30" 或 "for 10 days"。若沒寫有效期,穩固報價一般在「合理期間」內有效。"Subject to shipment by ..." 也是條件報價的一種。</p></div>`,
questions:[
{q:'賣方報價後,買方回覆「同意,但價格請降 5%」,此回覆在法律上屬於?',o:['接受','還價(Counter Offer)','詢價','撤回'],a:1,e:'接受必須「無條件、完全一致」,任何變更都是還價;還價等於拒絕原報價並提出新報價,原報價因此失效。'},
{q:'報價單上註明 "subject to our final confirmation",此報價屬於?',o:['穩固報價','條件報價','聯合報價','還價'],a:1,e:'「以我方最後確認為準」表示買方接受後還要賣方確認才成立契約,是不受拘束的條件報價(自由報價)。'},
{q:'穩固報價(Firm Offer)的特徵是?',o:['賣方可隨時撤回','有效期內賣方不得撤回,買方接受即成立契約','必須經買方確認','僅適用信用狀交易'],a:1,e:'Firm Offer 在有效期內「說話算話」,買方在期限內無條件接受,契約即告成立。'},
{q:'買方對報價逾期才回覆接受,此接受的效力為?',o:['當然有效','無效,除非賣方同意','視為新報價,賣方可自由決定是否接受','視為撤回'],a:2,e:'逾期接受(Late Acceptance)原則上不能成立契約,實務上視為買方提出的新報價,賣方可決定是否接受。選項 B 與 C 意思接近,但 C 描述更精確。'},
{q:'Proforma Invoice(形式發票)通常由誰簽發?用途為何?',o:['買方;作為付款憑證','賣方;作為報價與買方申請開狀、輸入許可之用','銀行;作為押匯憑證','海關;作為完稅憑證'],a:1,e:'P/I 是賣方出的「預期發票」,內容像正式發票但交易尚未完成,買方常用它向銀行申請開 L/C 或向政府申請進口許可。'},
{q:'Sales Confirmation(售貨確認書)是由何方簽發的契約文件?',o:['買方','賣方','船公司','開狀銀行'],a:1,e:'S/C 是賣方版契約;買方版是 Purchase Order(P/O)或 Purchase Confirmation。'},
{q:'賣方將 A、B、C 三項商品合併報價,並註明買方必須全部接受,此為?',o:['穩固報價','聯合報價','條件報價','交叉報價'],a:1,e:'聯合報價(Combined Offer)必須整批接受,不能只挑其中一項。'},
{q:'"Subject to prior sale" 在報價中的意思是?',o:['以先前售價為準','有貨先售為主,賣完就不受拘束','須事先付款','限首次訂購者'],a:1,e:'先售為主:貨賣完了報價就失效,屬於條件報價的一種。'},
{q:'契約成立的時點通常是?',o:['賣方寄出報價時','買方發出詢價時','買方對報價為有效接受時','買方付款時'],a:2,e:'報價 + 有效接受 = 契約成立(意思表示一致)。付款是契約履行,不是成立。'},
{q:'買方發出的詢價(Inquiry)在法律上屬於?',o:['要約','要約之引誘','承諾','契約'],a:1,e:'詢價只是「邀請對方報價」(要約之引誘),不具拘束力;報價(Offer)才是要約,接受(Acceptance)是承諾。'},
{q:'報價人在對方接受之前撤回報價的行為稱為?',o:['Acceptance','Counter Offer','Revocation / Withdrawal','Confirmation'],a:2,e:'撤回(Withdrawal,報價到達前)/ 撤銷(Revocation,到達後接受前)。穩固報價在有效期內原則上不得撤銷。'},
{q:'下列何者「不會」使報價失效?',o:['買方還價','有效期屆滿','買方在有效期內無條件接受','賣方在買方接受前撤銷'],a:2,e:'無條件接受會使契約成立,而不是失效;還價、逾期、撤銷都會讓報價失效。'}
]});

/* ===================== 5. 付款與融資 ===================== */
BANK.modules.push({
id:'m5', name:'國際貿易付款與融資', icon:'💳', short:'L/C 種類、D/P、D/A、T/T、O/A、貿易融資',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>跨國買賣最大的問題是「我先出貨你不付錢怎麼辦?」「我先付錢你不出貨怎麼辦?」付款方式就是各種「誰先冒險」的安排。<b>信用狀(L/C)</b>像找了一位有錢有信用的保證人(開狀銀行)站在中間:賣方只要把單據做對,銀行就付錢。</p></div>
<h4>付款方式光譜(對賣方安全 → 對買方有利)</h4>
<table><tr><th>方式</th><th>英文</th><th>誰先冒險</th><th>重點</th></tr>
<tr><td>預付貨款</td><td>CWO(Cash With Order)/ T/T in advance</td><td>買方</td><td>賣方最安全</td></tr>
<tr><td>信用狀</td><td>L/C(Letter of Credit)</td><td>銀行擔保</td><td>單據相符即付款;適用 UCP600</td></tr>
<tr><td>付款交單</td><td>D/P(Documents against Payment)</td><td>賣方(貨已出)</td><td>買方「付了錢」才能拿單據提貨;託收,適用 URC522</td></tr>
<tr><td>承兌交單</td><td>D/A(Documents against Acceptance)</td><td>賣方(風險更大)</td><td>買方在匯票上「承兌」(簽名承諾到期付款)就能先拿單據提貨</td></tr>
<tr><td>記帳</td><td>O/A(Open Account)</td><td>賣方</td><td>先出貨、約定日期再付款;賣方風險最高,只用於信任的老客戶</td></tr>
<tr><td>寄售</td><td>Consignment</td><td>賣方</td><td>貨賣掉才結帳</td></tr></table>
<p><b>電匯 T/T</b>(Telegraphic Transfer)是「匯款的方式」,可以搭配預付或記帳,本身不是一種擔保。</p>
<h4>信用狀的主要當事人</h4>
<table><tr><th>角色</th><th>英文</th><th>是誰</th></tr>
<tr><td>開狀申請人</td><td>Applicant</td><td>進口商(買方)</td></tr>
<tr><td>開狀銀行</td><td>Issuing / Opening Bank</td><td>買方的銀行,負最終付款責任</td></tr>
<tr><td>受益人</td><td>Beneficiary</td><td>出口商(賣方)</td></tr>
<tr><td>通知銀行</td><td>Advising Bank</td><td>出口地銀行,負責「核對真偽並轉交」L/C,不負付款責任</td></tr>
<tr><td>押匯銀行</td><td>Negotiating Bank</td><td>出口商拿單據去請款的銀行</td></tr>
<tr><td>保兌銀行</td><td>Confirming Bank</td><td>在開狀行之外「加一層保證」,通常是進口國風險高時用</td></tr>
<tr><td>補償銀行</td><td>Reimbursing Bank</td><td>開狀行指定代為付款給押匯行的銀行</td></tr></table>
<h4>信用狀的種類(考很細)</h4>
<ul><li><b>不可撤銷 Irrevocable</b>:UCP600 下所有 L/C 都是不可撤銷的(未註明也算)。</li>
<li><b>即期 Sight L/C</b>:單據到就付款;<b>遠期 Usance L/C</b>:承兌後到期付款(30/60/90 天)。遠期若利息由賣方負擔稱 Seller's Usance,由買方負擔稱 Buyer's Usance。</li>
<li><b>保兌 Confirmed</b>:多一家銀行保證;<b>無保兌 Unconfirmed</b>。</li>
<li><b>可轉讓 Transferable</b>:受益人可把 L/C 全部或部分轉給第二受益人,<b>只能轉讓一次</b>;L/C 必須明示 "transferable"。</li>
<li><b>背對背 Back-to-Back</b>:中間商拿原 L/C 當擔保,請銀行另開一張新 L/C 給供應商(三角貿易常用)。</li>
<li><b>循環 Revolving</b>:金額用完自動恢復,長期固定供貨用。</li>
<li><b>擔保 Standby</b>:平常不用,對方違約才動用,性質像保證函。</li>
<li><b>紅條款 Red Clause</b>:允許受益人在裝船前預支部分款項(裝船前融資)。</li>
<li><b>跟單 Documentary</b> vs <b>光票 Clean</b>:跟單要附貨運單據;光票只憑匯票。</li></ul>
<h4>貿易融資</h4>
<ul><li><b>出口押匯 Negotiation</b>:出口商憑 L/C 單據向銀行「先拿錢」(銀行墊款,若開狀行拒付可追索)。</li><li><b>打包放款 Packing Credit</b>:憑 L/C 在裝船前向銀行借錢備貨(裝船前融資)。</li><li><b>應收帳款承購 Factoring</b>:O/A、D/A 交易把應收帳款賣給承購商,通常短期、無追索。</li><li><b>Forfaiting(遠期票據買斷)</b>:買斷中長期的已承兌匯票,無追索權。</li><li><b>進口融資</b>:開狀額度、進口押匯、擔保提貨(Trust Receipt 信託收據)。</li></ul>`,
questions:[
{q:'在信用狀交易中,負「最終付款責任」的當事人是?',o:['通知銀行','押匯銀行','開狀銀行','進口商'],a:2,e:'開狀銀行(Issuing Bank)以自己的信用承諾:只要受益人提示相符單據就付款。通知銀行只負責核對真偽並轉交;押匯銀行是幫出口商墊款。'},
{q:'D/A(承兌交單)與 D/P(付款交單)的最大差別在?',o:['D/A 有銀行付款擔保','D/A 買方只要在匯票上承兌就能先取得單據提貨,D/P 要付款才能拿單據','D/P 是遠期付款','兩者相同'],a:1,e:'D/P:買方「付錢」才交單;D/A:買方「簽名承兌」就交單,貨先提走、到期再付——所以 D/A 對賣方風險比 D/P 高。兩者都是託收,銀行不擔保付款。'},
{q:'對出口商而言,下列付款方式風險由低到高的排序,何者正確?',o:['L/C < 預付 < D/P < O/A','預付 < L/C < D/P < D/A < O/A','O/A < D/A < D/P < L/C','D/P < L/C < 預付 < O/A'],a:1,e:'預付最安全(先收錢),其次 L/C(銀行擔保),D/P(付款才交單),D/A(承兌就交單),O/A 記帳最危險(先出貨等錢)。'},
{q:'信用狀交易適用的國際慣例是?',o:['URC522','UCP600','Incoterms 2020','ISBP'],a:1,e:'UCP600(信用狀統一慣例,2007 年版)規範 L/C;URC522 是託收(D/P、D/A)的規則;Incoterms 是貿易條件;ISBP 是審單的國際標準實務,輔助 UCP600。'},
{q:'可轉讓信用狀(Transferable L/C)最多可轉讓幾次?',o:['一次','兩次','三次','無限制'],a:0,e:'UCP600 規定可轉讓 L/C 只能轉讓一次(第一受益人轉給第二受益人),第二受益人不得再轉;且 L/C 必須明確載明 "transferable"。'},
{q:'中間商以國外買主開來的信用狀為擔保,請銀行另開一張信用狀給其供應商,此新信用狀稱為?',o:['循環信用狀','背對背信用狀','擔保信用狀','紅條款信用狀'],a:1,e:'Back-to-Back L/C:原 L/C(master)當擔保,另開一張新 L/C(baby)給供應商,三角貿易常用;兩張是獨立的信用狀。'},
{q:'允許受益人在裝船前預支部分貨款的信用狀是?',o:['Red Clause L/C','Standby L/C','Revolving L/C','Sight L/C'],a:0,e:'紅條款信用狀(早期以紅字書寫而得名)提供出口商裝船前的融資功能。'},
{q:'負責核對信用狀真偽並轉交給受益人的銀行是?',o:['開狀銀行','通知銀行','保兌銀行','補償銀行'],a:1,e:'通知銀行(Advising Bank)位於出口地,只負責確認 L/C 表面真實性並通知受益人,不負付款義務。'},
{q:'在進口國政治經濟風險較高時,出口商通常會要求信用狀加上?',o:['紅條款','保兌','可轉讓','循環'],a:1,e:'保兌(Confirmation)由另一家(通常是出口地)銀行加上獨立的付款承諾,即使開狀行倒閉或該國外匯管制,保兌行仍須付款。'},
{q:'依 UCP600,信用狀若未註明是否可撤銷,則視為?',o:['可撤銷','不可撤銷','無效','由通知銀行決定'],a:1,e:'UCP600 第 3 條:信用狀即使未表明,也是不可撤銷的。可撤銷信用狀已經不存在於 UCP600。'},
{q:'出口商憑信用狀在「裝船前」向銀行借款採購原料、備貨的融資方式稱為?',o:['出口押匯','打包放款','應收帳款承購','進口押匯'],a:1,e:'打包放款(Packing Credit)是裝船前融資;出口押匯(Negotiation)是裝船後憑單據取款。'},
{q:'關於「電匯 T/T」的敘述,下列何者正確?',o:['T/T 本身提供銀行付款擔保','T/T 是匯款方式,可搭配預付或記帳,不具擔保性質','T/T 必須附提單','T/T 只能用於遠期付款'],a:1,e:'T/T 只是「錢怎麼送過去」的工具,安全與否取決於是「先付(預付)」還是「後付(O/A)」。'},
{q:'遠期信用狀中,若貼現利息由買方負擔,稱為?',o:["Seller's Usance","Buyer's Usance",'Sight L/C','Deferred Payment'],a:1,e:"Buyer's Usance:買方享有延期付款但利息自己付,賣方可即期拿到全額;Seller's Usance 則由賣方負擔利息。"},
{q:'O/A(記帳)付款方式對出口商的主要風險是?',o:['匯率上升','貨物在運輸中滅失','貨已交付但買方不付款','銀行拒絕押匯'],a:2,e:'記帳是先出貨、到期才收款,完全靠買方信用,買方倒閉或賴帳出口商就收不到錢——可用輸出保險或 Factoring 降低風險。'},
{q:'將 O/A 或 D/A 交易產生的應收帳款賣給專業機構、提前取得資金的做法稱為?',o:['Factoring','Packing Credit','Negotiation','Trust Receipt'],a:0,e:'應收帳款承購(Factoring)適合短期、多筆的記帳交易;Forfaiting 是買斷中長期已承兌的匯票。'},
{q:'擔保信用狀(Standby L/C)的功能較接近?',o:['付款工具','保證函(對方違約才動用)','運送契約','保險單'],a:1,e:'Standby L/C 平常不動用,只在申請人違約時受益人才憑聲明請款,性質類似銀行保證函。'},
{q:'託收(D/P、D/A)交易中,銀行的角色是?',o:['擔保付款','代收代付,不負付款責任','審查貨物品質','代替買方提貨'],a:1,e:'託收銀行只是「跑腿」依指示交單、收款,買方不付款銀行不負責——這就是託收與信用狀的根本差別。'}
]});

/* ===================== 6. 國際運輸 ===================== */
BANK.modules.push({
id:'m6', name:'國際運輸', icon:'🚢', short:'海運、提單、貨櫃、空運、運費計算',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>海運像搭「公車」和「包車」:<b>定期船(Liner)</b>是公車,固定航線、固定班表、按件收費;<b>不定期船(Tramp)</b>是包車,整船租給你(傭船 Charter),適合大宗散裝貨(穀物、礦砂)。而<b>提單</b>就像「行李托運存根 + 領貨憑證」:沒有它就領不到貨。</p></div>
<h4>提單(Bill of Lading, B/L)三大功能</h4>
<ol><li><b>貨物收據</b>(運送人收到貨的證明)</li><li><b>運送契約的證明</b></li><li><b>物權憑證</b>(誰持有正本提單誰能提貨;可背書轉讓)</li></ol>
<h4>提單的種類(考試最愛)</h4>
<table><tr><th>分類</th><th>種類</th><th>重點</th></tr>
<tr><td>依貨物狀況</td><td>清潔提單 Clean B/L / 不清潔提單 Foul (Claused) B/L</td><td>L/C 要求 Clean;有「包裝破損」等批註就是不清潔</td></tr>
<tr><td>依是否裝船</td><td>裝船提單 On Board (Shipped) B/L / 備運提單 Received for Shipment B/L</td><td>L/C 通常要求 on board</td></tr>
<tr><td>依受貨人</td><td>記名提單 Straight B/L / 指示提單 Order B/L / 不記名提單 Bearer B/L</td><td>L/C 交易多用 "To order of issuing bank" 指示提單,可背書轉讓</td></tr>
<tr><td>依運費</td><td>Freight Prepaid(運費預付,CFR/CIF)/ Freight Collect(運費到付,FOB)</td><td>看誰付運費</td></tr>
<tr><td>其他</td><td>Stale B/L 陳舊提單:裝船後超過 21 天才提示;Through B/L 聯運提單;Multimodal Transport Document 複合運送單據;Sea Waybill 海運貨單(不可轉讓、不必憑正本提貨);Surrendered B/L 電放提單</td><td>UCP600:提示不得晚於裝船日後 21 天</td></tr></table>
<p><b>大副收據(Mate's Receipt, M/R)</b>:貨裝上船時大副簽的收據,憑它向船公司換正式提單。<b>裝貨單(Shipping Order, S/O)</b>:船公司給託運人的裝貨指示。<b>提貨單(Delivery Order, D/O)</b>:進口地憑提單換 D/O 才能到倉庫提貨。</p>
<h4>貨櫃運輸</h4>
<table><tr><th>名詞</th><th>意思</th></tr>
<tr><td>FCL(Full Container Load)整櫃</td><td>一個貨主裝滿一櫃;CY(Container Yard)貨櫃場交接</td></tr>
<tr><td>LCL(Less than Container Load)併櫃</td><td>多個貨主的貨合裝一櫃;CFS(Container Freight Station)貨櫃集散站交接</td></tr>
<tr><td>CY/CY</td><td>整櫃進整櫃出(FCL/FCL)</td></tr>
<tr><td>CFS/CFS</td><td>併櫃進併櫃出(LCL/LCL)</td></tr>
<tr><td>20' 標準櫃(TEU)</td><td>內容積約 <b>33 CBM</b>、載重約 21~28 噸</td></tr>
<tr><td>40' 標準櫃(FEU = 2 TEU)</td><td>約 <b>67 CBM</b></td></tr>
<tr><td>40' 高櫃(HQ / HC)</td><td>約 <b>76 CBM</b></td></tr>
<tr><td>THC</td><td>貨櫃場處理費;BAF 燃油附加費;CAF 幣值調整費;PSS 旺季附加費</td></tr></table>
<h4>運費計算(必考計算)</h4>
<ul><li><b>海運併櫃(LCL)常按「W/M」計費</b>:比較<b>重量噸</b>(1,000 kg = 1 噸)與<b>體積噸</b>(1 CBM = 1 噸),<b>取較大者</b>作為計費噸(Revenue Ton)。</li>
<li><b>材積(CBM)= 長 × 寬 × 高(公尺)× 箱數</b>。1 才(才積)= 1 立方英尺;1 CBM ≈ 35.3 才。</li>
<li><b>空運計費重量(Chargeable Weight)</b> = 實際重量與體積重量取<b>較大者</b>;體積重量 = 長×寬×高(公分)÷ <b>6,000</b>(即 1 CBM ≈ 167 kg)。</li>
<li>整櫃(FCL)按「每櫃」計費;定期船運費常含「基本運費 + 附加費」。</li></ul>
<div class="card example"><span class="deftag">例題</span><p>出口 100 箱貨,每箱 50×40×30 cm、毛重 12 kg,海運 LCL 運費 USD 60 / W/M。<br>材積 = 0.5×0.4×0.3×100 = 6 CBM;重量 = 1.2 噸。取較大者 6 → 運費 = 6 × 60 = <b>USD 360</b>。<br>同批貨改空運,體積重 = 50×40×30÷6000 = 10 kg/箱 < 實重 12 kg → 計費重量 = 12 × 100 = 1,200 kg。</p></div>
<h4>空運與複合運輸</h4>
<ul><li><b>空運提單 AWB(Air Waybill)</b>:<b>不是物權憑證、不可轉讓</b>,是記名的;貨到憑身分提貨。</li><li><b>複合運輸(Multimodal Transport)</b>:一份單據涵蓋海陸空兩種以上運輸,由複合運送人(MTO)負全程責任。</li><li><b>傭船契約(Charter Party)</b>:論程傭船 Voyage Charter、論時傭船 Time Charter、光船租賃 Bareboat Charter。</li></ul>`,
questions:[
{q:'提單(B/L)的三大功能「不包括」?',o:['貨物收據','運送契約證明','物權憑證','保險證明'],a:3,e:'提單 = 收據 + 運送契約證明 + 物權憑證;保險由保險單證明,與提單無關。'},
{q:'出口 200 箱貨物,每箱 60×50×40 公分、毛重 15 公斤,海運併櫃運費 USD 50 per W/M,運費為?',o:['USD 150','USD 600','USD 1,200','USD 3,000'],a:2,e:'材積 = 0.6×0.5×0.4 = 0.12 CBM/箱,×200 箱 = 24 CBM(體積噸 24);重量 = 15×200 = 3,000 kg = 3 噸。W/M 取較大者 24 噸 → 24 × 50 = USD 1,200。輕拋貨(體積大、重量輕)幾乎都是按體積計費。'},
{q:'空運貨物一箱 100×60×50 公分、實重 40 公斤,其計費重量為?',o:['40 kg','50 kg','60 kg','300 kg'],a:1,e:'體積重量 = 100×60×50 ÷ 6,000 = 50 kg,大於實重 40 kg,故計費重量取較大者 50 kg。'},
{q:'信用狀要求 "Clean on board B/L",下列哪一種提單「不符合」?',o:['註記 "shipped on board" 且無瑕疵批註','批註「3 cartons broken」','由船公司簽發、註明裝船日期','Freight prepaid 之裝船提單'],a:1,e:'有貨物或包裝瑕疵批註(如 3 箱破損)的提單是不清潔提單(Foul / Claused B/L),銀行會拒收。'},
{q:'受貨人欄位記載 "To order of XX Bank" 的提單是?',o:['記名提單','指示提單','不記名提單','海運貨單'],a:1,e:'"To order of ..." 是指示提單(Order B/L),可經背書轉讓,L/C 交易中常指示給開狀銀行以控制貨權。'},
{q:'依 UCP600,提單簽發後超過幾天才向銀行提示,即為「陳舊提單」?',o:['7 天','14 天','21 天','30 天'],a:2,e:'UCP600 第 14 條:單據提示不得遲於裝船日後 21 曆日,且不得逾信用狀有效期。超過 21 天的即 Stale B/L。'},
{q:'關於空運提單(AWB)的敘述,下列何者正確?',o:['是物權憑證,可背書轉讓','不是物權憑證,不可轉讓,受貨人憑身分提貨','與海運提單功能完全相同','由航空公司簽發後即成為保險單'],a:1,e:'AWB 是記名的、不可轉讓,只有收據與運送契約功能,沒有物權憑證功能——這是與海運提單最大的差別。'},
{q:'20 呎標準貨櫃的內容積約為?',o:['12 CBM','33 CBM','67 CBM','76 CBM'],a:1,e:'20\' ≈ 33 CBM(實務裝約 25~28 CBM);40\' ≈ 67 CBM;40\' HQ ≈ 76 CBM。'},
{q:'多位貨主的貨物合裝一個貨櫃,在貨櫃集散站交接,此為?',o:['FCL / CY','LCL / CFS','FCL / CFS','Bulk / Tramp'],a:1,e:'併櫃 LCL(Less than Container Load)在 CFS(Container Freight Station)拆併櫃;整櫃 FCL 在 CY 貨櫃場交接。'},
{q:'FOB 條件下簽發的提單,運費欄通常註明?',o:['Freight Prepaid','Freight Collect','Freight Free','Freight Included'],a:1,e:'FOB 運費由買方付,所以提單註明「運費到付」Freight Collect;CFR/CIF 則為 Freight Prepaid。'},
{q:'貨物裝上船後,由船上大副簽發、可用來向船公司換取正式提單的文件是?',o:['Shipping Order','Mate\'s Receipt','Delivery Order','Dock Receipt'],a:1,e:'大副收據(M/R)是船方收貨證明,託運人憑它換 B/L;S/O 是裝貨指示;D/O 是進口地提貨單。'},
{q:'定期船(Liner)與不定期船(Tramp)的主要差別是?',o:['定期船只載貨櫃','定期船有固定航線、船期與費率,不定期船則依傭船契約','不定期船速度較快','兩者運費計算方式相同'],a:1,e:'定期船像公車;不定期船像包車(傭船),多用於大宗散裝貨。'},
{q:'一份運送單據涵蓋海運與陸運全程、由單一運送人負責的運輸方式稱為?',o:['轉船運輸','複合運輸','傭船運輸','散裝運輸'],a:1,e:'複合運輸(Multimodal / Combined Transport)由 MTO 簽發複合運送單據並負全程責任,適合貨櫃 door-to-door。'},
{q:'BAF 是指?',o:['貨櫃場處理費','燃油附加費','幣值調整費','旺季附加費'],a:1,e:'BAF = Bunker Adjustment Factor 燃油附加費;CAF 幣值調整費;THC 貨櫃場處理費;PSS 旺季附加費。'},
{q:'海運併櫃貨物 3 CBM、重 4,000 kg,運費 USD 80 per W/M,運費為?',o:['USD 240','USD 320','USD 560','USD 80'],a:1,e:'重量噸 4 > 體積噸 3,取 4 噸 × 80 = USD 320。重貨看重量、輕拋貨看體積。'},
{q:'海運貨單(Sea Waybill)與提單的主要差異在?',o:['海運貨單可背書轉讓','海運貨單不是物權憑證,受貨人不必提示正本即可提貨','海運貨單只用於空運','海運貨單需由大副簽發'],a:1,e:'Sea Waybill 和 AWB 一樣屬「不可轉讓」單據,方便快速提貨,但賣方失去以單據控制貨物的功能,適合信任度高的交易。'},
{q:'1 CBM 約等於多少「才」(立方英尺)?',o:['10 才','35.3 才','100 才','1,000 才'],a:1,e:'1 公尺 ≈ 3.28 英尺,3.28³ ≈ 35.3,所以 1 CBM ≈ 35.3 才(cuft)。'}
]});

/* ===================== 7. 風險管理(保險) ===================== */
BANK.modules.push({
id:'m7', name:'國際貿易風險管理', icon:'🛡️', short:'海上貨物保險 ICC、保額、輸出保險、匯率風險',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>寄一台昂貴的相機出國,你會買「運送保險」;做國貿的貨要漂洋過海一個月,更要保。海上貨物保險就是「貨的旅行平安險」,<b>ICC(A)(B)(C)</b>就是三種方案:A 是「幾乎什麼都賠」的頂級方案,C 是「只賠大事故」的基本方案。</p></div>
<h4>協會貨物保險條款 ICC(Institute Cargo Clauses,2009 年版)</h4>
<table><tr><th>條款</th><th>承保範圍</th><th>對應舊條款(1963)</th></tr>
<tr><td><b>ICC(A)</b></td><td>「概括式」:除了除外不保事項,一切意外都賠(範圍最大、保費最高)</td><td>全險 All Risks(A/R)</td></tr>
<tr><td><b>ICC(B)</b></td><td>「列舉式」:C 的項目 + 地震、火山爆發、雷擊、海水湖水河水進入、整件貨物裝卸落海等</td><td>水漬險 WA(With Average)</td></tr>
<tr><td><b>ICC(C)</b></td><td>「列舉式」:只賠火災爆炸、船舶擱淺沉沒觸礁、碰撞、共同海損、投棄等重大事故</td><td>平安險 FPA(Free from Particular Average)</td></tr></table>
<p>三者共同的<b>除外不保</b>:被保險人故意行為、包裝不當、貨物本質瑕疵、遲延、船東無力償債、戰爭、罷工(戰爭險、罷工險要另外加保:Institute War Clauses、Institute Strikes Clauses)。<b>偷竊、短交(TPND)</b>只有 A 條款承保。</p>
<h4>保額與保費(必考計算)</h4>
<ul><li>慣例保額 = <b>CIF(或 CIP)發票金額 × 110%</b>(UCP600 也要求最低 110%;多出的 10% 是預期利潤)。</li><li><b>保費 = 保額 × 費率</b> = CIF × 1.1 × 費率。</li><li>由 CFR 推 CIF:<b>CIF = CFR ÷ (1 − 1.1 × 費率)</b>(因為保費本身也是 CIF 的一部分)。</li></ul>
<div class="card example"><span class="deftag">例題</span><p>CFR 為 USD 10,000,保險費率 0.5%,投保 110%。<br>CIF = 10,000 ÷ (1 − 1.1×0.005) = 10,000 ÷ 0.9945 ≈ <b>USD 10,055.30</b>;保額 = 10,055.30 × 1.1 ≈ 11,060.8;保費 = 11,060.8 × 0.5% ≈ <b>USD 55.30</b>。</p></div>
<h4>海損(Average)</h4>
<ul><li><b>全損 Total Loss</b>:實際全損 / 推定全損(修復費用超過貨值)。</li><li><b>共同海損 General Average(G.A.)</b>:為了全船安全「故意」犧牲部分貨物(如投棄),損失由船貨各方按比例分攤——三種 ICC 都賠。</li><li><b>單獨海損 Particular Average</b>:只有某貨主自己的貨損失,由自己(或其保險)承擔。</li></ul>
<h4>其他風險與工具</h4>
<table><tr><th>風險</th><th>工具</th></tr>
<tr><td>買方信用風險、進口國政治風險</td><td><b>輸出保險</b>(中華民國輸出入銀行)、要求 L/C 保兌、徵信</td></tr>
<tr><td>匯率風險</td><td><b>遠期外匯契約(Forward)</b>鎖定匯率、外匯選擇權、以本幣報價、自然避險(收付同幣別)</td></tr>
<tr><td>貨物運輸風險</td><td>海上貨物保險(誰投保看 Incoterms:CIF/CIP 賣方,FOB/CFR 買方)</td></tr>
<tr><td>價格風險</td><td>期貨、長約</td></tr></table>
<div class="card advanced"><span class="deftag">進階補充</span><p>保險單(Insurance Policy)可背書轉讓,保險證明書(Insurance Certificate)是預約保單(Open Policy)下的簡式證明;UCP600 接受保單與證明書,但<b>不接受</b>投保通知書(Cover Note)。保險單日期不得晚於裝船日(除非註明自裝船日起生效)。</p></div>`,
questions:[
{q:'CIF 條件下,依慣例與 UCP600,貨物保險的最低投保金額為?',o:['發票金額的 100%','發票金額的 110%','發票金額的 120%','FOB 金額的 110%'],a:1,e:'保額 = CIF 發票金額 × 110%,多出來的 10% 代表買方的預期利潤;UCP600 第 28 條也規定最低 110%。'},
{q:'CFR 金額 USD 20,000,保險費率 1%,按 110% 投保,則 CIF 價約為?',o:['USD 20,200','USD 20,220','USD 20,222','USD 22,000'],a:2,e:'CIF = CFR ÷ (1 − 1.1 × 1%) = 20,000 ÷ 0.989 ≈ 20,222.4。不能直接加 20,000×1.1×1% = 220,因為保費是以 CIF(不是 CFR)為基礎計算。'},
{q:'ICC(A)、(B)、(C) 三種條款中,承保範圍最廣的是?',o:['ICC(A)','ICC(B)','ICC(C)','三者相同'],a:0,e:'A 是概括式(除了除外事項全賠),B、C 是列舉式,C 範圍最小。A > B > C。'},
{q:'貨物在運送途中遭偷竊(TPND),下列何種條款可獲賠?',o:['ICC(C)','ICC(B)','ICC(A)','戰爭險'],a:2,e:'偷竊、短交(Theft, Pilferage and Non-Delivery)只有概括式的 ICC(A) 承保;B、C 是列舉式,沒有列的不賠。'},
{q:'為使船舶脫險而故意投棄部分貨物,損失由船貨各方按比例分攤,此稱為?',o:['單獨海損','共同海損','推定全損','實際全損'],a:1,e:'共同海損(General Average)的三要件:故意、合理、為共同安全;三種 ICC 條款都承保 G.A. 分攤。'},
{q:'ICC(A) 舊稱?',o:['平安險 FPA','水漬險 WA','全險 All Risks','兵險 War Risk'],a:2,e:'對應關係:A = 全險、B = 水漬險 WA、C = 平安險 FPA。'},
{q:'下列何者「不屬於」ICC 條款的共同除外不保事項?',o:['被保險人故意行為','包裝不當','船舶擱淺','遲延所致損失'],a:2,e:'擱淺是 C 條款就承保的重大事故;故意行為、包裝不當、遲延、貨物本質瑕疵、戰爭罷工(需加保)都是除外不保。'},
{q:'出口商擔心國外買主倒閉不付款,最適合投保?',o:['海上貨物保險 ICC(A)','輸出保險','火災保險','責任保險'],a:1,e:'輸出保險由輸出入銀行承保買方信用風險與進口國政治風險;貨物運輸保險只保貨物本身的損失。'},
{q:'出口商三個月後將收到 USD 100,000,擔心美元貶值,最直接的避險工具是?',o:['買海上保險','與銀行訂立遠期外匯契約預售美元','改用 D/A 付款','要求保兌'],a:1,e:'遠期外匯契約(Forward)現在就鎖定三個月後的匯率,不管屆時美元漲跌都按約定匯率結匯。'},
{q:'FOB 條件下,貨物運輸保險應由誰投保?',o:['賣方','買方','船公司','開狀銀行'],a:1,e:'FOB 風險在裝船時就轉給買方,之後的海上風險由買方承擔,自然由買方投保;CIF/CIP 才由賣方投保。'},
{q:'依 UCP600,下列哪種保險單據銀行「不接受」?',o:['保險單 Insurance Policy','保險證明書 Insurance Certificate','投保通知書 Cover Note','預約保單下的聲明書'],a:2,e:'Cover Note 只是經紀人的暫時通知,不是正式保險單據,UCP600 第 28 條明定不接受。'},
{q:'CIF 金額 USD 50,000,按 110% 投保 ICC(A),費率 0.3%,保費為?',o:['USD 150','USD 165','USD 1,500','USD 1,650'],a:1,e:'保額 = 50,000 × 1.1 = 55,000;保費 = 55,000 × 0.3% = USD 165。'},
{q:'海水進入船艙造成貨物受損,最低需投保哪種條款才可獲賠?',o:['ICC(C)','ICC(B)','ICC(A)','罷工險'],a:1,e:'「海水、湖水、河水進入船舶、貨櫃或儲存處所」是 ICC(B) 新增於 C 之上的列舉項目;C 不賠。'},
{q:'貨物修復費用已超過貨物本身價值,保險上稱為?',o:['實際全損','推定全損','共同海損','單獨海損'],a:1,e:'推定全損(Constructive Total Loss):貨物雖然還在,但修復或救回的費用超過價值,被保險人可委付給保險人並按全損理賠。'},
{q:'關於保險單日期,依 UCP600 下列何者正確?',o:['可以晚於裝船日','不得晚於裝船日,除非註明自裝船日起承保','必須與信用狀開狀日相同','必須晚於提單日期'],a:1,e:'保險必須在裝船時已生效,所以保單日期不得晚於裝船日(除非保單註明保險自裝船日起生效)。'}
]});

/* ===================== 8. 進出口結匯 ===================== */
BANK.modules.push({
id:'m8', name:'進出口結匯', icon:'🏦', short:'匯票、出口押匯、單據審查、進口贖單、擔保提貨',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>「結匯」就是把「貨」變成「錢」的最後一哩路。出口商拿著一疊單據(像拿著兌獎券)到銀行「押匯」換現金;進口商則到銀行「付款贖單」,像去便利商店付錢取包裹。</p></div>
<h4>匯票(Bill of Exchange / Draft)</h4>
<table><tr><th>要件</th><th>說明</th></tr>
<tr><td>發票人 Drawer</td><td>出口商(受益人)</td></tr>
<tr><td>付款人 Drawee</td><td>L/C 交易:通常是<b>開狀銀行</b>(UCP600 規定不得以申請人為付款人);託收交易:進口商</td></tr>
<tr><td>受款人 Payee</td><td>通常是押匯銀行(或出口商)</td></tr>
<tr><td>期限 Tenor</td><td>即期 at sight;遠期 at 60 days after sight(見票後)/ after date(發票日後)/ after B/L date(提單日後)</td></tr>
<tr><td>金額</td><td>文字與數字並列;依 L/C 規定百分比(通常 100% of invoice value)</td></tr></table>
<p>匯票的行為:<b>承兌 Acceptance</b>(付款人簽名承諾到期付款)、<b>背書 Endorsement</b>(轉讓)、<b>拒付 Dishonor</b>。</p>
<h4>出口結匯(押匯 Negotiation)</h4>
<ol><li>裝船後備齊 L/C 要求的單據(匯票、發票、裝箱單、提單、保單、產證等)。</li><li>在 L/C 有效期內、裝船後 21 天內向押匯銀行提示。</li><li>銀行審單:<b>單據與信用狀相符、單據彼此一致</b>(嚴格一致原則)。</li><li>相符 → 銀行墊付貨款(扣利息、手續費),再向開狀行求償。</li><li>單據有瑕疵(Discrepancy)→ 可「電詢」開狀行、「保結押匯」(出口商出具保證書)、或改「託收」方式。</li></ol>
<p>UCP600 重點:銀行有<b>最多 5 個銀行營業日</b>審單;「單據交易」原則——銀行只看單據,不管貨物;拒付須一次列明所有瑕疵。</p>
<h4>進口結匯</h4>
<ul><li><b>開狀</b>:進口商向銀行申請開 L/C,繳保證金、手續費;銀行審核額度。</li><li><b>贖單</b>:單據到達,即期 L/C 進口商付款取單;遠期 L/C 承兌後取單、到期付款。</li><li><b>擔保提貨(L/G, Letter of Guarantee)</b>:貨到但正本提單未到,進口商請開狀行出具擔保書向船公司先提貨,日後正本提單到再補交;提貨後<b>不得再以單據瑕疵拒付</b>。</li><li><b>副提單背書</b>:進口商持副本提單請銀行背書後提貨(常見於近洋航線)。</li><li><b>信託收據(T/R)</b>:進口商先向銀行借出單據提貨,貨物所有權仍屬銀行,售貨後還款。</li></ul>
<h4>常見瑕疵(Discrepancy)</h4>
<p>逾期提示、逾期裝船、L/C 過期、提單不清潔、金額超過 L/C、單據間資料不一致(數量、嘜頭、品名)、缺少單據、保額不足、匯票期限錯誤、未依規定份數。</p>`,
questions:[
{q:'在信用狀交易中,出口商所開匯票的付款人(Drawee)通常是?',o:['進口商','開狀銀行','通知銀行','船公司'],a:1,e:'UCP600 規定 L/C 下的匯票不得以申請人(進口商)為付款人,通常以開狀銀行(或其指定銀行)為付款人;託收交易的匯票付款人才是進口商。'},
{q:'匯票上記載 "at 60 days after sight",指付款期限為?',o:['開票後 60 天','見票(承兌)後 60 天','裝船後 60 天','到貨後 60 天'],a:1,e:'after sight = 見票後;after date = 發票日後;after B/L date = 提單日後。'},
{q:'出口商將單據提示給銀行、由銀行先墊付貨款的行為稱為?',o:['開狀','押匯','贖單','託收'],a:1,e:'押匯(Negotiation)= 銀行買入單據/匯票並墊款給出口商,之後再向開狀行求償。'},
{q:'依 UCP600,銀行審查單據的期限最多為提示日後幾個銀行營業日?',o:['3 天','5 天','7 天','21 天'],a:1,e:'UCP600 第 14 條:最多 5 個銀行營業日決定提示是否相符;21 天是提單後提示的期限,不要混淆。'},
{q:'貨物已到港,但正本提單尚未寄達,進口商可向開狀銀行申請何種文件先行提貨?',o:['擔保提貨書 L/G','信託收據 T/R','裝船通知','大副收據'],a:0,e:'擔保提貨(Letter of Guarantee)由銀行擔保向船公司先提貨,正本提單到後再補交;辦理後進口商不得再以單據瑕疵拒付。'},
{q:'銀行審查信用狀單據時所遵循的原則是?',o:['只要貨物品質良好即可','單據必須表面上與信用狀條款相符且彼此一致','以進口商的意見為準','以船公司的認定為準'],a:1,e:'信用狀是「單據交易」:銀行只審單據不看貨,單據須與 L/C 相符並互相一致(嚴格一致原則)。'},
{q:'單據有瑕疵時,出口商出具保證書後請銀行仍予押匯,稱為?',o:['電詢押匯','保結押匯','託收','轉押匯'],a:1,e:'保結押匯(Negotiation under Reserve / against Indemnity):出口商保證若開狀行拒付則退還款項。電詢是先發電報問開狀行是否接受瑕疵。'},
{q:'下列何者「不屬於」常見的單據瑕疵?',o:['提單日期晚於信用狀最後裝船日','發票金額超過信用狀金額','單據在有效期內提示','保險金額不足 110%'],a:2,e:'在有效期內提示是正確的做法;逾期裝船、超額、保額不足都是典型瑕疵。'},
{q:'進口商向銀行借出單據先行提貨、貨物所有權仍屬於銀行的文件是?',o:['擔保提貨書','信託收據 T/R','副提單','託收指示'],a:1,e:'信託收據(Trust Receipt)是進口融資工具:銀行放單給進口商賣貨,貨款回收後再還銀行。'},
{q:'匯票的發票人(Drawer)在信用狀交易中通常是?',o:['進口商','開狀銀行','出口商(受益人)','通知銀行'],a:2,e:'出口商是受益人,由他簽發匯票向付款人(開狀行)請款。'},
{q:'即期信用狀(Sight L/C)下,進口商何時付款贖單?',o:['貨物出售後','單據到達開狀行、經審核相符時即付款','匯票承兌後 90 天','裝船前'],a:1,e:'Sight = 見單即付;遠期(Usance)才是承兌後到期付款。'},
{q:'匯票付款人在匯票上簽名承諾到期付款的行為稱為?',o:['背書','承兌','拒付','貼現'],a:1,e:'承兌(Acceptance)是遠期匯票的關鍵動作;背書是轉讓;貼現是持票人提前向銀行換現金(扣利息)。'},
{q:'依 UCP600,開狀行決定拒付時,應如何通知?',o:['可分次告知瑕疵','須一次列明所有瑕疵並敘明單據處置方式','僅需通知進口商','不必說明理由'],a:1,e:'UCP600 第 16 條:拒付通知須一次載明所有瑕疵,並說明單據留置或退回等處置,否則不得主張單據不符。'}
]});

/* ===================== 9. 索賠與糾紛 ===================== */
BANK.modules.push({
id:'m9', name:'貿易索賠與糾紛處理', icon:'⚖️', short:'買賣索賠、運輸索賠、保險索賠、仲裁與不可抗力',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>網購收到瑕疵品你會「申請退貨」——找誰?賣家、物流、還是保險?國貿也一樣,索賠要先找對對象:貨本身有問題找<b>賣方</b>;運送途中摔壞找<b>運送人</b>;有保險就找<b>保險公司</b>。談不攏時,先「調解」、再「仲裁」、最後才「打官司」。</p></div>
<h4>索賠(Claim)的三種對象</h4>
<table><tr><th>種類</th><th>對象</th><th>常見原因</th><th>重點</th></tr>
<tr><td>買賣索賠(貿易索賠)</td><td>賣方 / 買方</td><td>品質不符、數量短少、遲延交貨、包裝不良;買方不開狀、不付款</td><td>需在契約約定的索賠期限內提出,附公證報告(Survey Report)</td></tr>
<tr><td>運輸索賠</td><td>運送人(船公司)</td><td>貨物在運送人保管期間毀損滅失</td><td>海牙規則下運送人責任有限額,且對「航行過失」免責</td></tr>
<tr><td>保險索賠</td><td>保險公司</td><td>承保範圍內的事故</td><td>提出保單、提單、發票、公證報告、向運送人索賠的證明</td></tr></table>
<h4>糾紛解決方式(由軟到硬)</h4>
<ol><li><b>和解 / 協商</b>(Negotiation)</li><li><b>調解</b>(Mediation / Conciliation):第三人協助,無拘束力</li><li><b>仲裁</b>(Arbitration):雙方事先在契約約定「仲裁條款」,由仲裁人裁決,<b>一裁終局、具法律拘束力</b>,快速、保密、費用較低;台灣由「中華民國仲裁協會」辦理;國際上常用 ICC 國際仲裁院</li><li><b>訴訟</b>(Litigation):法院判決,耗時、公開、跨國執行困難</li></ol>
<h4>不可抗力(Force Majeure)</h4>
<p>戰爭、天災、罷工、政府禁令等<b>當事人無法控制、無法預見</b>的事件導致無法履約,可免除違約責任;契約應載明不可抗力條款與通知義務(通常需在一定期限內通知並提供證明,如商會出具的證明書)。<b>市場價格變動、原料漲價不算不可抗力</b>。</p>
<div class="card advanced"><span class="deftag">進階補充</span><p>公證行(Surveyor,如 SGS)出具的公證報告是索賠最重要的證據。索賠成立後的處理:退貨、換貨、減價、賠償損失、取消契約。輸出保險理賠與貨物保險理賠不同——前者賠「收不到錢」,後者賠「貨壞了」。</p></div>`,
questions:[
{q:'貨物到港後發現因船艙進水受損,若已投保 ICC(B),買方應優先向誰索賠?',o:['賣方','保險公司','報關行','開狀銀行'],a:1,e:'運送途中的事故損失在承保範圍內時,向保險公司索賠最直接;保險公司賠付後再代位向運送人求償。'},
{q:'契約中約定「爭議交由仲裁解決」,仲裁判斷的效力為?',o:['僅供參考,無拘束力','與法院確定判決有同一效力,一裁終局','須經法院重新審理','僅對賣方有拘束力'],a:1,e:'仲裁判斷具有法律拘束力,原則上不得上訴(一裁終局),且可依紐約公約在各國執行,比訴訟快且保密。'},
{q:'下列何者「不屬於」不可抗力事件?',o:['戰爭','颱風地震','政府禁運','原料價格大漲'],a:3,e:'不可抗力必須是無法預見、無法控制的事件;價格波動是商業風險,不能作為免責理由。'},
{q:'買方發現貨物品質與樣品不符,提出索賠時最重要的證據文件是?',o:['商業發票','公證報告(Survey Report)','提單','匯票'],a:1,e:'由獨立公證行(如 SGS)出具的公證報告是證明貨物狀況的客觀證據,買賣、運輸、保險索賠都需要。'},
{q:'由第三人協助雙方達成協議、但無法律拘束力的糾紛解決方式是?',o:['仲裁','調解','訴訟','公證'],a:1,e:'調解(Mediation)結果要雙方同意才生效;仲裁判斷則有拘束力。'},
{q:'關於仲裁與訴訟的比較,下列何者正確?',o:['仲裁較耗時','仲裁程序公開','仲裁通常較快速、保密且費用較低','訴訟判決不能上訴'],a:2,e:'仲裁的優點:快、保密、專業、跨國執行方便(紐約公約);訴訟則公開且可能歷經多審。'},
{q:'賣方遲延交貨導致買方損失,買方應向誰提出索賠?',o:['船公司','保險公司','賣方','通知銀行'],a:2,e:'遲延交貨是賣方的契約責任,屬買賣索賠。保險不賠遲延(除外事項),船公司也非責任方。'},
{q:'台灣辦理商務仲裁的主要機構是?',o:['中華民國仲裁協會','經濟部國際貿易署','外貿協會','台北地方法院'],a:0,e:'中華民國仲裁協會依仲裁法辦理仲裁;國際上常見 ICC 國際仲裁院、新加坡國際仲裁中心等。'},
{q:'契約中訂有索賠期限(如「貨到後 30 天內」)的主要目的是?',o:['方便賣方提高價格','避免買方在貨物已使用或轉售後才提出爭議','讓運送人免責','讓保險公司免責'],a:1,e:'索賠期限保護賣方,避免時隔太久證據滅失、責任難以釐清;逾期提出賣方可拒絕。'},
{q:'發生不可抗力事件時,受影響的一方通常應?',o:['不必通知對方','立即通知對方並在期限內提供證明文件','自行取消契約','向保險公司索賠'],a:1,e:'不可抗力條款通常要求「及時通知 + 提供證明」(如商會證明),否則不得主張免責。'},
{q:'買方以「不開發信用狀」方式拒絕履約,對賣方而言這屬於?',o:['運輸索賠','保險索賠','買方違約的買賣索賠事由','不可抗力'],a:2,e:'買方應依約開狀,不開狀就是違約,賣方可要求損害賠償或解除契約。'}
]});

/* ===================== 10. 價格計算 ===================== */
BANK.modules.push({
id:'m10', name:'價格計算', icon:'🧮', short:'FOB/CFR/CIF 換算、保費、佣金、利潤、匯率、進口稅費',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>報價像「算一碗滷肉飯要賣多少」:成本(進貨)+ 想賺的(利潤)+ 外送費(運費)+ 保險 + 平台抽成(佣金)。不同貿易條件只是「哪些費用包進價格裡」的差別:<b>FOB 不含運保費、CFR 含運費、CIF 含運費+保費</b>。</p></div>
<h4>核心公式(背下來)</h4>
<table><tr><th>換算</th><th>公式</th><th>備註</th></tr>
<tr><td>CFR</td><td>CFR = FOB + 運費(F)</td><td>運費用「加」的</td></tr>
<tr><td>CIF</td><td><b>CIF = (FOB + F) ÷ (1 − 1.1 × 保險費率)</b> = CFR ÷ (1 − 1.1r)</td><td>保費是 CIF 的一部分,所以要用「除」</td></tr>
<tr><td>保費</td><td>保費 = CIF × 110% × 費率</td><td>保額 = CIF × 1.1</td></tr>
<tr><td>FOB(由 CIF 反推)</td><td>FOB = CIF × (1 − 1.1r) − F</td><td>先扣保費再扣運費</td></tr>
<tr><td>含佣價</td><td><b>FOBC5 = FOB ÷ (1 − 5%)</b>;佣金 = 含佣價 × 5%</td><td>佣金以「含佣價」為基礎算</td></tr>
<tr><td>利潤(以售價為基礎)</td><td>售價 = 成本 ÷ (1 − 利潤率)</td><td>「售價的 10%」用除法</td></tr>
<tr><td>利潤(以成本為基礎)</td><td>售價 = 成本 × (1 + 加成率)</td><td>「成本加 10%」用乘法</td></tr>
<tr><td>匯率換算</td><td>台幣成本 ÷ 匯率(TWD/USD)= 美元價</td><td>匯率 32 表示 1 USD = 32 TWD</td></tr></table>
<h4>進口稅費(台灣)</h4>
<ul><li><b>完稅價格(DPV)= CIF 價格</b>(以起岸價格為準)</li><li><b>進口關稅 = 完稅價格 × 關稅稅率</b></li><li><b>貨物稅 =(完稅價格 + 關稅)× 貨物稅率</b>(僅特定貨品,如汽車、飲料)</li><li><b>營業稅 =(完稅價格 + 關稅 + 貨物稅)× 5%</b></li><li><b>推廣貿易服務費 = 完稅價格 × 0.04%</b></li><li>進口總成本 = CIF + 關稅 + 貨物稅 + 營業稅 + 推廣費 + 其他(報關費、倉租等)</li></ul>
<div class="card example"><span class="deftag">完整例題</span><p>某貨 FOB Keelung USD 8,000,海運費 USD 500,保險費率 0.4%(投保 110%),買方要求 CIF 報價含 3% 佣金。<br>① CFR = 8,000 + 500 = 8,500<br>② CIF = 8,500 ÷ (1 − 1.1×0.004) = 8,500 ÷ 0.9956 ≈ 8,537.57<br>③ CIFC3 = 8,537.57 ÷ (1 − 0.03) ≈ <b>8,801.62</b><br>佣金 = 8,801.62 × 3% ≈ 264.05。</p></div>
<div class="card advanced"><span class="deftag">計算題心法</span><p>①「含在價格裡、又按價格的百分比算」的東西(保費、佣金、以售價為基礎的利潤)一律用<b>除以 (1 − 比率)</b>;②「固定金額」的東西(運費、報關費)用<b>加減</b>;③ 最後再<b>四捨五入到小數 2 位</b>,選項通常差很多,先估數量級再細算。</p></div>`,
questions:[
{q:'FOB 價 USD 5,000,運費 USD 300,保險費率 0.5%,投保 110%,CIF 價約為?',o:['USD 5,300.00','USD 5,329.15','USD 5,316.50','USD 5,330.00'],a:1,e:'CIF = (5,000+300) ÷ (1 − 1.1×0.005) = 5,300 ÷ 0.9945 ≈ 5,329.31。四個選項中最接近正確值(5,329.3)的是 B。注意:直接加 5,300×1.1×0.5% = 29.15 得 5,329.15 是常見的近似算法,考試若兩者都出現,以「除法」結果為準。'},
{q:'CIF 價 USD 12,000,運費 USD 800,保險費率 1%(110%),則 FOB 價約為?',o:['USD 11,068','USD 11,200','USD 11,332','USD 10,868'],a:0,e:'FOB = CIF × (1 − 1.1r) − F = 12,000 × 0.989 − 800 = 11,868 − 800 = USD 11,068。反推時先扣保費(乘法)再扣運費。'},
{q:'FOB 價 USD 9,500,買方要求含 5% 佣金的 FOBC5 報價為?',o:['USD 9,975','USD 10,000','USD 10,025','USD 9,025'],a:1,e:'FOBC5 = 9,500 ÷ (1 − 0.05) = 10,000;佣金 = 10,000 × 5% = 500,賣方淨得 9,500。若用 9,500 × 1.05 = 9,975 是錯的——佣金是以含佣價為基礎。'},
{q:'產品成本 TWD 640,希望利潤為「售價的 20%」,匯率 1 USD = 32 TWD,美元售價為?',o:['USD 24','USD 25','USD 20','USD 26'],a:1,e:'售價(TWD)= 640 ÷ (1 − 0.2) = 800;÷ 32 = USD 25。「售價的 20%」用除法;若是「成本加 20%」則為 640×1.2 = 768 → USD 24。'},
{q:'進口貨物 CIF 完稅價格 TWD 1,000,000,關稅稅率 10%,無貨物稅,營業稅 5%,應繳營業稅為?',o:['TWD 50,000','TWD 55,000','TWD 100,000','TWD 5,000'],a:1,e:'關稅 = 1,000,000×10% = 100,000;營業稅 = (1,000,000 + 100,000) × 5% = 55,000。營業稅的稅基包含關稅。'},
{q:'台灣進口貨物的「完稅價格」是以何種價格為基準?',o:['FOB','CFR','CIF','EXW'],a:2,e:'台灣採 CIF(起岸價格)作為完稅價格(Duty Paying Value),包含貨價、運費與保險費。'},
{q:'推廣貿易服務費的費率為完稅價格的?',o:['0.04%','0.4%','4%','0.004%'],a:0,e:'推廣貿易服務費 = 完稅價格 × 萬分之四(0.04%),用於外貿協會等推廣經費。'},
{q:'CFR 價 USD 30,000,保險費率 0.2%,投保 110%,則保費約為?',o:['USD 60','USD 66','USD 66.15','USD 600'],a:2,e:'CIF = 30,000 ÷ (1 − 1.1×0.002) = 30,000 ÷ 0.9978 ≈ 30,066.15;保費 = CIF − CFR = 66.15(也 = 30,066.15×1.1×0.2%)。直接 30,000×1.1×0.2% = 66 是近似值,精確值為 66.15。'},
{q:'某商品 FOB 每件 USD 10,買方訂購 1,000 件,運費每 CBM USD 40,每箱 20 件、每箱 0.05 CBM,則 CFR 總價為?',o:['USD 10,100','USD 10,200','USD 12,000','USD 10,040'],a:0,e:'箱數 = 1,000÷20 = 50 箱;材積 = 50×0.05 = 2.5 CBM;運費 = 2.5×40 = 100;CFR = 10,000 + 100 = USD 10,100。'},
{q:'匯率由 1 USD = 30 TWD 變為 1 USD = 32 TWD,對台灣出口商以美元報價的影響是?',o:['收到的台幣減少','收到的台幣增加','沒有影響','必須降價'],a:1,e:'美元升值(台幣貶值),同樣的美元換到更多台幣,對出口商有利;對進口商則成本上升。'},
{q:'成本 USD 800,以「成本加成 25%」報價,再含 4% 佣金,含佣價為?',o:['USD 1,040.00','USD 1,041.67','USD 1,000.00','USD 1,032.00'],a:1,e:'售價 = 800 × 1.25 = 1,000;含佣價 = 1,000 ÷ (1 − 0.04) = 1,041.67。'},
{q:'進口汽車 CIF TWD 2,000,000,關稅 17.5%,貨物稅 25%,營業稅 5%,貨物稅額為?',o:['TWD 500,000','TWD 587,500','TWD 350,000','TWD 625,000'],a:1,e:'關稅 = 2,000,000×17.5% = 350,000;貨物稅 = (2,000,000 + 350,000) × 25% = 587,500。貨物稅的稅基是「完稅價格 + 關稅」。'}
]});

/* ===================== 11. 基礎貿易英文 ===================== */
BANK.modules.push({
id:'m11', name:'基礎貿易英文', icon:'🔤', short:'書信結構、常用句型、縮寫、單據與 L/C 英文',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>貿易英文不是寫作文,是「填公式」:每封信都是 <b>開場(謝謝來信)→ 正事(報價/回覆)→ 結尾(期待回音)</b>。單字也很固定,把縮寫表背熟,考題大半是「這個縮寫是什麼」「這句話在說什麼」。</p></div>
<h4>英文書信結構</h4>
<ol><li>Letterhead 信頭(公司名稱地址)</li><li>Date 日期</li><li>Inside Address 收信人地址</li><li>Salutation 稱呼:Dear Mr. Smith, / Dear Sirs,</li><li>Subject line 主旨:Re: Your Inquiry No. 123</li><li>Body 本文</li><li>Complimentary Close 結尾敬語:Sincerely yours, / Best regards,</li><li>Signature 簽名</li><li>Enclosure 附件:Encl.</li></ol>
<h4>萬用句型</h4>
<table><tr><th>情境</th><th>句型</th></tr>
<tr><td>感謝來信</td><td>Thank you for your inquiry of May 5 regarding ...</td></tr>
<tr><td>報價</td><td>We are pleased to quote as follows: / We offer you firm, subject to your reply reaching us by June 30, ...</td></tr>
<tr><td>價格條件</td><td>USD 12.50 per piece CIF Los Angeles</td></tr>
<tr><td>付款</td><td>Payment: by irrevocable L/C at sight in our favor.</td></tr>
<tr><td>交貨</td><td>Shipment: within 30 days after receipt of your L/C.</td></tr>
<tr><td>附件</td><td>Enclosed please find our latest catalog and price list.</td></tr>
<tr><td>還價</td><td>We regret that your price is too high / We can accept your offer if you reduce the price by 5%.</td></tr>
<tr><td>催款/催開狀</td><td>Please open the L/C as soon as possible so that we can effect shipment on time.</td></tr>
<tr><td>索賠</td><td>We have to lodge a claim against you for the shortage of 50 cartons.</td></tr>
<tr><td>結尾</td><td>We look forward to receiving your order. / We hope to establish business relations with you.</td></tr></table>
<h4>必背縮寫(考試超愛)</h4>
<table><tr><th>縮寫</th><th>全名</th><th>中文</th></tr>
<tr><td>L/C</td><td>Letter of Credit</td><td>信用狀</td></tr><tr><td>B/L</td><td>Bill of Lading</td><td>提單</td></tr><tr><td>AWB</td><td>Air Waybill</td><td>空運提單</td></tr><tr><td>P/I</td><td>Proforma Invoice</td><td>形式發票</td></tr><tr><td>P/O</td><td>Purchase Order</td><td>訂購單</td></tr><tr><td>S/C</td><td>Sales Confirmation / Contract</td><td>售貨確認書</td></tr><tr><td>C/O</td><td>Certificate of Origin</td><td>產地證明書</td></tr><tr><td>P/L</td><td>Packing List</td><td>裝箱單</td></tr><tr><td>D/P、D/A</td><td>Documents against Payment / Acceptance</td><td>付款交單 / 承兌交單</td></tr><tr><td>T/T</td><td>Telegraphic Transfer</td><td>電匯</td></tr><tr><td>O/A</td><td>Open Account</td><td>記帳</td></tr><tr><td>ETD / ETA</td><td>Estimated Time of Departure / Arrival</td><td>預計開航日 / 到達日</td></tr><tr><td>MOQ</td><td>Minimum Order Quantity</td><td>最低訂購量</td></tr><tr><td>FCL / LCL</td><td>Full / Less than Container Load</td><td>整櫃 / 併櫃</td></tr><tr><td>CY / CFS</td><td>Container Yard / Container Freight Station</td><td>貨櫃場 / 貨櫃集散站</td></tr><tr><td>THC</td><td>Terminal Handling Charge</td><td>貨櫃場處理費</td></tr><tr><td>CBM</td><td>Cubic Meter</td><td>立方公尺(材積)</td></tr><tr><td>G.W. / N.W.</td><td>Gross / Net Weight</td><td>毛重 / 淨重</td></tr><tr><td>S/O</td><td>Shipping Order</td><td>裝貨單</td></tr><tr><td>D/O</td><td>Delivery Order</td><td>提貨單</td></tr><tr><td>UCP</td><td>Uniform Customs and Practice for Documentary Credits</td><td>信用狀統一慣例</td></tr><tr><td>ICC</td><td>International Chamber of Commerce / Institute Cargo Clauses</td><td>國際商會 / 協會貨物條款</td></tr><tr><td>HS</td><td>Harmonized System</td><td>國際商品統一分類制度</td></tr><tr><td>WTO</td><td>World Trade Organization</td><td>世界貿易組織</td></tr><tr><td>FTA</td><td>Free Trade Agreement</td><td>自由貿易協定</td></tr><tr><td>EXW…DDP</td><td>Incoterms 2020</td><td>見第 3 章</td></tr></table>
<p>更多單字請用「單字卡」模式練習。</p>`,
questions:[
{q:'"Enclosed please find our price list." 中 "Enclosed" 的意思是?',o:['已寄出','隨函附上','已收到','請確認'],a:1,e:'Enclosed please find ... = 隨函附上……,信末常標 Encl. 表示有附件。'},
{q:'"We offer you firm, subject to your reply reaching us by June 30." 此句表示?',o:['這是條件報價','這是有效期至 6 月 30 日的穩固報價','這是還價','報價已撤回'],a:1,e:'offer firm = 穩固報價;subject to your reply reaching us by ... 是有效期限的寫法。'},
{q:'"Payment: by irrevocable L/C at sight in our favor." 中 "in our favor" 的意思是?',o:['對我方有利的價格','以我方為受益人','由我方付款','由我方通知'],a:1,e:'in favor of / in our favor = 以……為受益人(Beneficiary);L/C in your favor 就是以你方為受益人的信用狀。'},
{q:'ETA 是指?',o:['預計開航時間','預計到達時間','實際裝船時間','報關截止時間'],a:1,e:'ETA = Estimated Time of Arrival 預計到達;ETD = Estimated Time of Departure 預計開航。'},
{q:'"We have to lodge a claim against you for the short shipment." 這句話的目的是?',o:['下訂單','提出索賠','報價','催開信用狀'],a:1,e:'lodge / file a claim = 提出索賠;short shipment = 短裝(數量不足)。'},
{q:'MOQ 是指?',o:['最低訂購量','最高品質','每月出貨量','最低報價'],a:0,e:'MOQ = Minimum Order Quantity,賣方接受的最小訂單量。'},
{q:'"Please effect shipment within 30 days after receipt of L/C." 中 "effect shipment" 意為?',o:['取消裝船','影響裝船','辦理裝船','延後裝船'],a:2,e:'effect shipment = 辦理/執行裝運(effect 當動詞 = 使……實現),是貿易英文的固定用法。'},
{q:'商業書信中 "Dear Sirs," 之後的結尾敬語,較正式且搭配的是?',o:['Love,','Yours faithfully,','See you,','Cheers,'],a:1,e:'英式用法:Dear Sirs → Yours faithfully;Dear Mr. Smith → Yours sincerely。美式常用 Sincerely yours。'},
{q:'"Your price is out of line with the market." 意思是?',o:['你方價格符合市場','你方價格與市場行情不符(偏高)','你方價格太低','市場沒有此產品'],a:1,e:'out of line with = 與……不一致;這是還價時常用的委婉說法,暗示對方價格偏高。'},
{q:'"Notify Party" 在提單上是指?',o:['託運人','受貨人','貨到時應通知的人','船長'],a:2,e:'Notify Party = 到貨通知人,船公司到港時通知他;通常是進口商或其報關行。'},
{q:'"Freight Prepaid" 表示?',o:['運費到付','運費預付','運費免收','運費待議'],a:1,e:'Prepaid = 預付(賣方付,CFR/CIF);Collect = 到付(買方付,FOB)。'},
{q:'"We look forward to establishing business relations with you." 是用於?',o:['索賠信','開發信/建立業務關係','拒絕信','催款信'],a:1,e:'establish business relations = 建立業務關係,是開發信(first letter)的標準結尾句。'},
{q:'"Discrepancy" 在信用狀作業中指?',o:['折扣','單據與信用狀不符之瑕疵','貨物短缺','匯率差異'],a:1,e:'Discrepancy = 瑕疵、不符點,是押匯被拒付的原因;Amendment 則是修改信用狀。'},
{q:'"Beneficiary" 在信用狀中指?',o:['開狀申請人','受益人(出口商)','通知銀行','押匯銀行'],a:1,e:'Beneficiary = 受益人 = 出口商;Applicant = 申請人 = 進口商。'},
{q:'"Partial shipments are allowed." 意為?',o:['禁止分批裝運','允許分批裝運','允許轉運','禁止轉運'],a:1,e:'Partial shipment = 分批裝運;Transhipment = 轉運。allowed / permitted 允許,prohibited / not allowed 禁止。'},
{q:'"Please quote your best price CIF Hamburg." 買方要求的是?',o:['漢堡港的 FOB 報價','含運保費至漢堡港的報價','工廠交貨價','稅訖交貨價'],a:1,e:'quote ... CIF + 目的港 = 請報含運費保險費到該港的價格。'},
{q:'"Counter sample" 是指?',o:['櫃台樣品','對等樣品(賣方依買方樣品製作的回樣)','免費樣品','參考樣品'],a:1,e:'Counter sample 是賣方按買方樣品仿製、寄回確認的樣品,確認後成為品質標準。'},
{q:'"The goods are packed in cartons of 12 pcs each, 50 cartons to a pallet." 一個棧板有幾件?',o:['12','50','600','62'],a:2,e:'12 pcs × 50 cartons = 600 pcs。pcs = pieces;pallet = 棧板。'}
]});

/* ===================== 12. 信用狀實例分析與單證填製 ===================== */
BANK.modules.push({
id:'m12', name:'信用狀實例分析與單證填製', icon:'📄', short:'SWIFT MT700 欄位、單據填製、審單一致性',
notes: `
<div class="card metaphor"><span class="tag">生活比喻</span><p>信用狀像一張「任務卡」:上面寫了金額、期限、要交哪些文件、每份文件要長什麼樣。出口商的工作是<b>照卡片一字不差地做出所有文件</b>——少一份、寫錯一個字、晚一天,銀行都可以不付錢。所以「讀懂 L/C 欄位」和「把單據填對」是這章的全部。</p></div>
<h4>SWIFT MT700 信用狀常考欄位</h4>
<table><tr><th>欄位</th><th>名稱</th><th>意思</th></tr>
<tr><td>31C</td><td>Date of Issue</td><td>開狀日</td></tr>
<tr><td><b>31D</b></td><td>Date and Place of Expiry</td><td><b>有效期限與地點</b>(在出口地到期對受益人有利)</td></tr>
<tr><td>50</td><td>Applicant</td><td>開狀申請人(進口商)</td></tr>
<tr><td>59</td><td>Beneficiary</td><td>受益人(出口商)</td></tr>
<tr><td>32B</td><td>Currency Code, Amount</td><td>幣別與金額</td></tr>
<tr><td>39A</td><td>Percentage Credit Amount Tolerance</td><td>金額寬容度(如 05/05 表示 ±5%)</td></tr>
<tr><td>41A/D</td><td>Available With ... By ...</td><td>可在哪家銀行以何種方式使用(by negotiation 押匯 / by payment / by acceptance / by deferred payment)</td></tr>
<tr><td><b>42C</b></td><td>Drafts at ...</td><td><b>匯票期限</b>(at sight / 60 days after sight)</td></tr>
<tr><td>42A</td><td>Drawee</td><td>匯票付款人</td></tr>
<tr><td>43P</td><td>Partial Shipments</td><td>分批裝運 allowed / prohibited</td></tr>
<tr><td>43T</td><td>Transhipment</td><td>轉運 allowed / prohibited</td></tr>
<tr><td>44E / 44F</td><td>Port of Loading / Port of Discharge</td><td>裝貨港 / 卸貨港</td></tr>
<tr><td><b>44C</b></td><td>Latest Date of Shipment</td><td><b>最後裝船日</b></td></tr>
<tr><td>45A</td><td>Description of Goods</td><td>貨物描述(發票的品名必須與此一致)</td></tr>
<tr><td><b>46A</b></td><td>Documents Required</td><td><b>應提示單據</b></td></tr>
<tr><td>47A</td><td>Additional Conditions</td><td>附加條件</td></tr>
<tr><td>48</td><td>Period for Presentation</td><td>提示期間(未載明則為裝船後 21 天)</td></tr>
<tr><td>49</td><td>Confirmation Instructions</td><td>保兌指示(CONFIRM / WITHOUT / MAY ADD)</td></tr>
<tr><td>71B</td><td>Charges</td><td>費用負擔(通常出口地費用由受益人負擔)</td></tr></table>
<h4>單據填製要點</h4>
<table><tr><th>單據</th><th>誰做</th><th>必對的欄位</th></tr>
<tr><td>商業發票 Commercial Invoice</td><td>受益人</td><td>抬頭開給申請人;品名<b>必須與 45A 完全一致</b>;金額不得超過 L/C;貿易條件;不必簽署(除非 L/C 要求)</td></tr>
<tr><td>裝箱單 Packing List</td><td>受益人</td><td>件數、毛淨重、材積、嘜頭要與發票、提單一致</td></tr>
<tr><td>提單 B/L</td><td>運送人</td><td>Consignee 依 L/C(常為 "to order of issuing bank");Notify party;裝卸港;on board 註記與日期;clean;運費 prepaid/collect;全套正本(通常 3/3)</td></tr>
<tr><td>保險單 Insurance Policy</td><td>保險公司</td><td>幣別同 L/C;金額 ≥ CIF 110%;條款依 L/C;日期不晚於裝船日;被保險人依 L/C(常需空白背書)</td></tr>
<tr><td>匯票 Draft</td><td>受益人</td><td>期限依 42C;付款人依 42A;金額同發票;註明 "Drawn under L/C No. ... dated ..."</td></tr>
<tr><td>產地證明 C/O</td><td>公會 / 商會</td><td>出口商、產地、品名一致</td></tr></table>
<h4>審單三個「一致」</h4>
<ol><li><b>單據與 L/C 一致</b>(品名、金額、港口、期限、份數)</li><li><b>單據之間一致</b>(發票、裝箱單、提單的數量、重量、嘜頭)</li><li><b>三個日期</b>:裝船日 ≤ 44C 最後裝船日;提示日 ≤ 裝船後 21 天;提示日 ≤ 31D 有效期</li></ol>
<div class="card example"><span class="deftag">實例</span><p>L/C:31D 2026-07-15 Taipei;44C 2026-06-30;48 未載明;46A:signed commercial invoice in 3 copies, full set clean on board B/L to order of issuing bank marked freight prepaid, insurance policy for 110% ICC(A)。<br>提單裝船日 2026-06-28 ✔(≤ 6/30);最遲提示日 = 6/28 + 21 天 = 7/19,但不得超過 7/15 → <b>7/15 前</b>要提示 ✔;發票要簽名、3 份;提單受貨人寫 "To order of [開狀銀行]";保單保額 = 發票 × 110%、ICC(A)。</p></div>`,
questions:[
{q:'信用狀 44C 欄位 "Latest Date of Shipment" 指的是?',o:['信用狀有效期限','最後裝船日','最後提示日','開狀日'],a:1,e:'44C = 最後裝船日;31D = 有效期限;48 = 提示期間。提單的裝船日不得晚於 44C。'},
{q:'L/C 規定 44C 為 6 月 30 日、31D 為 7 月 20 日、48 未載明;提單裝船日 6 月 25 日,最遲應於何日前提示單據?',o:['6 月 30 日','7 月 16 日','7 月 20 日','7 月 25 日'],a:1,e:'未載明提示期間 → 裝船後 21 天 = 6/25 + 21 = 7/16;且不得超過有效期 7/20。兩者取較早的 7/16。'},
{q:'信用狀 42C 欄位 "Drafts at 90 days after sight" 表示?',o:['即期匯票','見票後 90 天付款的遠期匯票','提單日後 90 天付款','開狀日後 90 天付款'],a:1,e:'42C 是匯票期限;after sight 指見票(承兌)後起算。'},
{q:'L/C 要求提單 "made out to order of issuing bank",提單受貨人欄應填?',o:['進口商名稱','To order of [開狀銀行名稱]','To order of shipper','受益人名稱'],a:1,e:'依 L/C 指示填「憑開狀銀行指示」,讓開狀行在進口商付款前控制貨權。'},
{q:'商業發票上的貨物描述(Description of Goods)必須與信用狀哪一欄位相符?',o:['46A','45A','47A','44C'],a:1,e:'UCP600 第 18 條:發票貨物描述必須與 L/C(45A)相符;其他單據可用不牴觸的統稱。'},
{q:'信用狀 39A 欄位記載 "05/05",表示?',o:['分 5 批裝運','金額可增減 5%','5 份單據','5 天內提示'],a:1,e:'39A = Percentage Credit Amount Tolerance,05/05 表示金額上下 5% 的寬容度。'},
{q:'信用狀規定 "Insurance policy for 110% of invoice value covering ICC(A)",若發票金額 USD 40,000,保單金額應為?',o:['USD 40,000','USD 44,000','USD 48,000','USD 36,000'],a:1,e:'40,000 × 110% = USD 44,000;條款須為 ICC(A);幣別同 L/C。'},
{q:'信用狀 41D 記載 "Available with any bank by negotiation",表示?',o:['僅限開狀行付款','受益人可向任何銀行押匯','必須到進口國付款','僅能以承兌方式使用'],a:1,e:'Available with any bank = 自由押匯信用狀;by negotiation = 以押匯方式使用。'},
{q:'審核單據時,下列何者屬於「單據間不一致」的瑕疵?',o:['發票數量 1,000 pcs、裝箱單 1,000 pcs、提單 50 cartons','發票嘜頭 ABC、提單嘜頭 ABD','三份發票皆有簽名','提單註明 clean on board'],a:1,e:'嘜頭在發票與提單上不同,屬單據彼此不一致的瑕疵。A 選項中件數單位不同但可對應(1,000 pcs 裝 50 箱),不算矛盾。'},
{q:'信用狀 31D "Date and Place of Expiry: 2026-08-31 Taipei",對受益人的意義是?',o:['必須在台北的銀行於 8/31 前完成提示','必須在 8/31 前到貨','貨物必須 8/31 前裝船','8/31 前開狀'],a:0,e:'有效地點在出口地(台北)對受益人有利,只要 8/31 前在台北的銀行完成提示即可,不必擔心郵寄到開狀行的時間。'},
{q:'信用狀規定 "Full set of clean on board ocean B/L",若船公司簽發 3 份正本提單,受益人應提示?',o:['1 份正本','2 份正本','3 份正本全套','副本即可'],a:2,e:'Full set = 全套正本(3/3);提單是物權憑證,少一份代表可能有人能憑那份提貨,銀行不接受。'},
{q:'匯票上 "Drawn under XX Bank L/C No. 12345 dated May 1, 2026" 的作用是?',o:['指定運送人','註明匯票所依據的信用狀','指定受貨人','說明貨物內容'],a:1,e:'出票條款(Drawn under clause)註明匯票依據哪張 L/C 簽發,方便銀行核對。'},
{q:'信用狀 43T 記載 "Transhipment: Prohibited",但提單顯示在新加坡轉船,依 UCP600?',o:['一定是瑕疵','若同一份提單涵蓋全程運送且為貨櫃運輸,銀行仍可接受','需進口商同意','需船公司出具證明'],a:1,e:'UCP600 第 20 條:即使 L/C 禁止轉運,只要同一份提單涵蓋全程且貨物以貨櫃、拖車或子母船運送,註明可能轉運的提單仍可接受。'},
{q:'信用狀規定 "Commercial invoice in 3 copies, signed",受益人提示未簽名的發票,結果為?',o:['可接受','屬瑕疵,可能被拒付','僅需補簽一份','由開狀行代簽'],a:1,e:'L/C 明文要求 signed,未簽就是不符;若 L/C 沒要求簽名,發票依 UCP600 可以不簽。'}
]});

